// English Practice — Question Bank
// Each question: { id, type: 'vocab'|'phrase'|'grammar', cat: 'daily'|'travel', text, correct, distractors: [3], ex }
// "text" uses ___ as the blank. "correct" + "distractors" are combined and shuffled at runtime.
// To add more questions later: just append objects with a new unique id.

export const QUESTIONS = [
  // ---------- Original set (1-40) ----------
  {id:1, type:"phrase", cat:"daily", text:"Could you ___ me a favor and pick up some milk on your way home?", correct:"do", distractors:["take","give","make"], ex:"請人幫忙的固定搭配是 do me a favor，不能用 make / give / take。"},
  {id:2, type:"phrase", cat:"travel", text:"Excuse me, do you have anything to ___ at customs?", correct:"declare", distractors:["say","announce","tell"], ex:"海關常用語 anything to declare，表示「需要申報的物品」。"},
  {id:3, type:"grammar", cat:"daily", text:"I'm sorry I'm late — something urgent ___ up at the last minute.", correct:"has come", distractors:["came","comes","come"], ex:"強調對現在造成的影響，要用現在完成式 has come up。"},
  {id:4, type:"phrase", cat:"travel", text:"I'd like to check ___ now. Here's my passport and reservation.", correct:"in", distractors:["on","up","at"], ex:"飯店「辦理入住」的固定用法是 check in。"},
  {id:5, type:"phrase", cat:"daily", text:"Could you keep ___ on my bag while I use the restroom?", correct:"an eye", distractors:["a look","a watch","a sight"], ex:"「幫忙看著東西」的慣用語是 keep an eye on something。"},
  {id:6, type:"grammar", cat:"travel", text:"Is breakfast ___ in the room rate, or is it extra?", correct:"included", distractors:["include","includes","including"], ex:"be 動詞 + 過去分詞構成被動語態，表示「被包含在內」。"},
  {id:7, type:"grammar", cat:"daily", text:"I haven't seen you ___ ages! How have you been?", correct:"for", distractors:["since","from","in"], ex:"現在完成式搭配一段時間長度用 for，搭配明確時間點才用 since。"},
  {id:8, type:"grammar", cat:"travel", text:"Excuse me, which platform does the train to Queenstown ___ from?", correct:"leave", distractors:["leaves","leaving","left"], ex:"句中已有助動詞 does，後面動詞要還原成原形 leave。"},
  {id:9, type:"phrase", cat:"daily", text:"Sorry, could you say that again? I didn't quite ___ it.", correct:"catch", distractors:["get","hold","keep"], ex:"「沒聽清楚」的口語說法是 catch what someone said。"},
  {id:10, type:"phrase", cat:"travel", text:"We're fully booked tonight, but I can put you ___ the waiting list.", correct:"on", distractors:["in","at","to"], ex:"「列入候補名單」的固定搭配是 put someone on the waiting list。"},
  {id:11, type:"vocab", cat:"daily", text:"He's been feeling under the weather, so he stayed home today. What does 'under the weather' mean?", correct:"Sick", distractors:["Tired","Busy","Sad"], ex:"under the weather 是常見口語，意思是「身體不舒服」。"},
  {id:12, type:"grammar", cat:"travel", text:"Could you recommend a local dish that's especially ___ around here?", correct:"popular", distractors:["popularity","populate","popularly"], ex:"需要形容詞修飾名詞 dish，故選 popular。"},
  {id:13, type:"phrase", cat:"daily", text:"I can't talk right now — can I call you ___ in ten minutes?", correct:"back", distractors:["again","later","return"], ex:"「回電」的固定用法是 call someone back。"},
  {id:14, type:"grammar", cat:"travel", text:"How long does it ___ to get to the airport from downtown?", correct:"take", distractors:["spend","cost","need"], ex:"詢問花費時間用句型 it takes + 時間，spend 的主詞須是人。"},
  {id:15, type:"phrase", cat:"daily", text:"Don't worry about the bill — it's ___ me this time.", correct:"on", distractors:["in","for","to"], ex:"「這次我請客」的口語說法是 It's on me。"},
  {id:16, type:"vocab", cat:"travel", text:"Is this seat taken, or is it ___?", correct:"free", distractors:["empty","vacant","alone"], ex:"詢問座位是否有人坐，口語常用 Is this seat free?"},
  {id:17, type:"phrase", cat:"daily", text:"I've been meaning to call you, but I just haven't ___ around to it.", correct:"got", distractors:["gone","come","made"], ex:"get around to + N/Ving 表示「終於抽空做某事」。"},
  {id:18, type:"phrase", cat:"travel", text:"Could you tell me how to ___ to the nearest pharmacy?", correct:"get", distractors:["go","walk","reach"], ex:"問路常用句型 How to get to + 地點。"},
  {id:19, type:"grammar", cat:"daily", text:"She's really good ___ dealing with difficult customers.", correct:"at", distractors:["in","for","with"], ex:"be good at + Ving 表示「擅長於」。"},
  {id:20, type:"phrase", cat:"travel", text:"We got caught ___ in traffic and missed our connecting flight.", correct:"up", distractors:["in","on","at"], ex:"get caught up in traffic 表示「被困在車陣中」。"},
  {id:21, type:"grammar", cat:"daily", text:"Could you turn the volume down? It's a bit ___ loud.", correct:"too", distractors:["so","very","much"], ex:"too + 形容詞表示「過於」，帶有負面語氣，符合語境。"},
  {id:22, type:"vocab", cat:"travel", text:"Excuse me, is there a currency exchange ___ here in the airport?", correct:"nearby", distractors:["near","close","closely"], ex:"nearby 可直接修飾地點，表示「附近的」。"},
  {id:23, type:"phrase", cat:"daily", text:"I'm trying to cut ___ on sugar, so I'll skip dessert.", correct:"down", distractors:["off","out","up"], ex:"cut down on + N 表示「減少攝取」。"},
  {id:24, type:"grammar", cat:"travel", text:"The flight has been delayed ___ to bad weather.", correct:"due", distractors:["owing","because","caused"], ex:"due to + 名詞表示「由於」。"},
  {id:25, type:"grammar", cat:"daily", text:"He apologized ___ being late to the meeting.", correct:"for", distractors:["to","about","of"], ex:"apologize for + N/Ving 表示「為某事道歉」。"},
  {id:26, type:"phrase", cat:"travel", text:"Could I have a window seat ___ possible?", correct:"if", distractors:["when","as","in"], ex:"if possible 是常見插入語，表示「如果可以的話」。"},
  {id:27, type:"grammar", cat:"daily", text:"I'm looking forward ___ seeing you next week.", correct:"to", distractors:["for","on","at"], ex:"look forward to + Ving，這裡的 to 是介系詞而非不定詞。"},
  {id:28, type:"phrase", cat:"travel", text:"Sorry, I'm a bit lost — could you point me ___ the right direction?", correct:"in", distractors:["to","at","on"], ex:"point someone in the right direction 是固定片語，表示「指引方向」。"},
  {id:29, type:"phrase", cat:"daily", text:"It's been raining ___ and off all day.", correct:"on", distractors:["off","in","at"], ex:"on and off 表示「斷斷續續」。"},
  {id:30, type:"grammar", cat:"travel", text:"Could you let me know ___ the bus arrives?", correct:"once", distractors:["until","while","during"], ex:"once 在此作連接詞，表示「一旦…」。"},
  {id:31, type:"grammar", cat:"daily", text:"I'd rather you ___ smoke in here, if that's okay.", correct:"didn't", distractors:["don't","won't","not"], ex:"would rather + 主詞 + 過去式動詞，是委婉的請求或建議句型。"},
  {id:32, type:"grammar", cat:"travel", text:"Do you know of any good restaurants ___ within walking distance?", correct:"that are", distractors:["which is","who are","what are"], ex:"先行詞 restaurants 為複數，關代子句動詞需用 are，指物用 that/which。"},
  {id:33, type:"phrase", cat:"daily", text:"I haven't decided yet — I'm still weighing ___ my options.", correct:"up", distractors:["on","in","for"], ex:"weigh up one's options 表示「仔細考慮各種選擇」。"},
  {id:34, type:"phrase", cat:"travel", text:"Make sure you keep your passport with you at ___ times.", correct:"all", distractors:["the","any","every"], ex:"at all times 是固定片語，表示「隨時、一直」。"},
  {id:35, type:"grammar", cat:"daily", text:"I can't believe how time flies — it feels ___ yesterday that we graduated.", correct:"like", distractors:["as","such","so"], ex:"feel like + 子句，表示「感覺像是…」。"},
  {id:36, type:"grammar", cat:"travel", text:"The tour guide told us to meet ___ the lobby at 8 a.m. sharp.", correct:"in", distractors:["at","on","to"], ex:"在室內空間（大廳）用介系詞 in。"},
  {id:37, type:"phrase", cat:"daily", text:"Could you give me a hand ___ these boxes? They're really heavy.", correct:"with", distractors:["for","to","of"], ex:"give someone a hand with + N，表示「幫忙做某事」。"},
  {id:38, type:"phrase", cat:"travel", text:"We should book the hotel ___ advance to get a better rate.", correct:"in", distractors:["on","at","by"], ex:"in advance 表示「提前」。"},
  {id:39, type:"phrase", cat:"daily", text:"He's not much ___ a cook, but he tries his best.", correct:"of", distractors:["as","for","like"], ex:"not much of a + N 表示「算不上是…」，是常見口語句型。"},
  {id:40, type:"grammar", cat:"travel", text:"Let's ask the front desk if they can arrange a taxi ___ us.", correct:"for", distractors:["to","with","of"], ex:"arrange something for someone 表示「為某人安排某事」。"},

  // ---------- Grammar batch (41-80) ----------
  {id:41, type:"grammar", cat:"daily", text:"She has lived in Taipei ___ she was born.", correct:"since", distractors:["for","during","while"], ex:"since + 時間點，表示「從某個時間點開始」；for + 一段時間長度。"},
  {id:42, type:"grammar", cat:"travel", text:"If it ___ tomorrow, we'll just visit the museum instead.", correct:"rains", distractors:["will rain","rained","is raining"], ex:"第一類條件句：if 子句用現在簡單式，主句才用 will。"},
  {id:43, type:"grammar", cat:"daily", text:"I wish I ___ more time to relax these days.", correct:"had", distractors:["have","will have","having"], ex:"wish + 過去式表達對現在的不滿或假設，用過去簡單式。"},
  {id:44, type:"grammar", cat:"travel", text:"By the time we arrived at the gate, the plane ___ already.", correct:"had left", distractors:["left","has left","was leaving"], ex:"過去完成式表示在過去某個時間點之前已完成的動作。"},
  {id:45, type:"grammar", cat:"daily", text:"He suggested ___ a different route to avoid traffic.", correct:"taking", distractors:["to take","take","took"], ex:"suggest + Ving，不能接 to V。"},
  {id:46, type:"grammar", cat:"travel", text:"This is the hotel ___ we stayed last summer.", correct:"where", distractors:["which","that","when"], ex:"先行詞是地點，關係副詞用 where。"},
  {id:47, type:"grammar", cat:"daily", text:"There ___ a lot of traffic on the highway this morning.", correct:"was", distractors:["were","is","are"], ex:"traffic 是不可數名詞，動詞要用單數 was。"},
  {id:48, type:"grammar", cat:"travel", text:"Could you tell me ___ the museum opens?", correct:"what time", distractors:["what time does","when does","what time is"], ex:"間接問句語序是「疑問詞+主詞+動詞」，不能用一般問句的倒裝。"},
  {id:49, type:"grammar", cat:"daily", text:"I'm used ___ early for work every day.", correct:"to getting up", distractors:["to get up","getting up","get up"], ex:"be used to + Ving 表示「已經習慣於」。"},
  {id:50, type:"grammar", cat:"travel", text:"The longer we waited, ___ we got.", correct:"the more impatient", distractors:["more impatient","the most impatient","much more impatient"], ex:"the + 比較級, the + 比較級，表示「越…就越…」。"},
  {id:51, type:"grammar", cat:"daily", text:"Neither of the two restaurants ___ open on Mondays.", correct:"is", distractors:["are","were","have been"], ex:"Neither of + 複數名詞，動詞視為單數，用 is。"},
  {id:52, type:"grammar", cat:"travel", text:"We need to find out ___ the local currency is worth.", correct:"how much", distractors:["how many","what","how"], ex:"詢問金額、價值用 how much。"},
  {id:53, type:"grammar", cat:"daily", text:"My phone needs ___; the screen is cracked.", correct:"fixing", distractors:["to fixing","fix","fixed"], ex:"need + Ving（主動形式表被動）等於 need to be fixed。"},
  {id:54, type:"grammar", cat:"travel", text:"Had I known about the strike, I ___ a different flight.", correct:"would have booked", distractors:["would book","will book","booked"], ex:"與過去事實相反的假設句（倒裝），主句用 would have + p.p.。"},
  {id:55, type:"grammar", cat:"daily", text:"She's the kind of person who always ___ her promises.", correct:"keeps", distractors:["keep","is keeping","kept"], ex:"先行詞 person 是第三人稱單數，關係子句動詞要配合用 keeps。"},
  {id:56, type:"grammar", cat:"travel", text:"Despite the heavy rain, the tour ___ ahead as planned.", correct:"went", distractors:["go","goes","has gone"], ex:"描述過去發生的事，用過去簡單式 went。"},
  {id:57, type:"grammar", cat:"daily", text:"Not only ___ late, but he also forgot his wallet.", correct:"was he", distractors:["he was","he is","is he"], ex:"Not only 放句首時，後面要倒裝，主詞和動詞對調。"},
  {id:58, type:"grammar", cat:"travel", text:"We'd better ___ a taxi instead of walking in this heat.", correct:"take", distractors:["to take","taking","took"], ex:"had better + 原形動詞，表示「最好…」。"},
  {id:59, type:"grammar", cat:"daily", text:"This book is ___ than the one I read last month.", correct:"far more interesting", distractors:["more interesting far","much interesting","far interesting"], ex:"far + 比較級用來加強語氣，表示「…得多」。"},
  {id:60, type:"grammar", cat:"travel", text:"The luggage ___ to the wrong carousel by mistake.", correct:"was sent", distractors:["sent","has sent","was sending"], ex:"行李是被「送」到錯誤轉盤，要用被動語態 was sent。"},
  {id:61, type:"grammar", cat:"daily", text:"I'd rather have stayed home than ___ to that boring party.", correct:"gone", distractors:["go","went","going"], ex:"would rather have + p.p. than (have) + p.p.，表達對過去的懊悔。"},
  {id:62, type:"grammar", cat:"travel", text:"Make sure your passport ___ for at least six months.", correct:"is valid", distractors:["valid","validates","will valid"], ex:"需要完整的 be 動詞 + 形容詞結構，valid 是形容詞。"},
  {id:63, type:"grammar", cat:"daily", text:"It's high time we ___ this old car.", correct:"replaced", distractors:["replace","will replace","are replacing"], ex:"it's (high) time + 子句用過去式，表示「該是…的時候了」。"},
  {id:64, type:"grammar", cat:"travel", text:"Few tourists ___ aware of the local customs before they arrive.", correct:"are", distractors:["is","was","has been"], ex:"Few tourists 是複數主詞，動詞要用 are。"},
  {id:65, type:"grammar", cat:"daily", text:"I can't help ___ how much things have changed.", correct:"noticing", distractors:["to notice","notice","noticed"], ex:"can't help + Ving 表示「忍不住…」。"},
  {id:66, type:"grammar", cat:"travel", text:"The flight attendant asked us ___ our seatbelts.", correct:"to fasten", distractors:["fastening","fasten","fastened"], ex:"ask someone to V 是常見的受詞補語句型。"},
  {id:67, type:"grammar", cat:"daily", text:"Hardly ___ the meeting started when his phone rang.", correct:"had", distractors:["did","has","was"], ex:"Hardly + had + 主詞 + p.p.，倒裝句表示「幾乎一…就…」。"},
  {id:68, type:"grammar", cat:"travel", text:"This is one of the most beautiful places I ___ ever visited.", correct:"have", distractors:["had","has","was"], ex:"one of the + 最高級 + 名詞 + (that) + 主詞 + have ever + p.p.，現在完成式表示「至今為止」。"},
  {id:69, type:"grammar", cat:"daily", text:"She seems ___ about the new project.", correct:"excited", distractors:["exciting","excite","to excite"], ex:"人對某事感到興奮，要用過去分詞形容詞 excited。"},
  {id:70, type:"grammar", cat:"travel", text:"Provided that the weather ___ fine, we'll go hiking tomorrow.", correct:"is", distractors:["will be","were","would be"], ex:"provided that 引導條件句，子句用現在式表示未來。"},
  {id:71, type:"grammar", cat:"daily", text:"He always insists on ___ for everyone when they go out.", correct:"paying", distractors:["pay","to pay","paid"], ex:"insist on + Ving，介系詞後面要接動名詞。"},
  {id:72, type:"grammar", cat:"travel", text:"The tour guide recommended that we ___ early to avoid the crowds.", correct:"arrive", distractors:["arrived","arriving","will arrive"], ex:"recommend that + 主詞 + 原形動詞（假設語氣），不受人稱與時態影響。"},
  {id:73, type:"grammar", cat:"daily", text:"I haven't finished the report yet — I ___ it by Friday though.", correct:"will have finished", distractors:["will finish","finish","am finishing"], ex:"未來完成式表示在未來某個時間點之前會完成的動作。"},
  {id:74, type:"grammar", cat:"travel", text:"Whoever ___ the lost passport, please hand it in at the front desk.", correct:"finds", distractors:["found","will find","is finding"], ex:"複合關係代名詞 whoever 引導的子句，描述一般情況用現在式。"},
  {id:75, type:"grammar", cat:"daily", text:"I'd appreciate it if you ___ keep this between us.", correct:"could", distractors:["can","will","would have"], ex:"I'd appreciate it if + 過去式助動詞，是禮貌且委婉的請求語氣。"},
  {id:76, type:"grammar", cat:"travel", text:"There's no point ___ for a table without a reservation on Saturday nights.", correct:"waiting", distractors:["to wait","wait","waited"], ex:"there's no point (in) + Ving，表示「…是沒有意義的」。"},
  {id:77, type:"grammar", cat:"daily", text:"The more you practice, ___ you'll become.", correct:"the more confident", distractors:["more confident","the most confident","much confident"], ex:"the + 比較級, the + 比較級 句型，前後結構要對稱。"},
  {id:78, type:"grammar", cat:"travel", text:"We were told that the museum ___ closed for renovations.", correct:"was", distractors:["is","has been","were"], ex:"主要子句是過去式 were told，依時態一致原則，子句也用過去式 was。"},
  {id:79, type:"grammar", cat:"daily", text:"Scarcely ___ sat down when the waiter came to take our order.", correct:"had we", distractors:["we had","did we","have we"], ex:"Scarcely + had + 主詞 + p.p. 是倒裝句，表示「幾乎一…就…」。"},
  {id:80, type:"grammar", cat:"travel", text:"It is essential that every passenger ___ their boarding pass ready.", correct:"have", distractors:["has","having","will have"], ex:"it is essential that + 主詞 + 原形動詞（假設語氣），不論主詞為何都用原形。"},

  // ---------- Phrase batch (81-120) ----------
  {id:81, type:"phrase", cat:"daily", text:"Could you fill me ___ on what happened at the meeting I missed?", correct:"in", distractors:["up","out","off"], ex:"fill someone in (on something) 表示「跟某人說明最新狀況」。"},
  {id:82, type:"phrase", cat:"travel", text:"We should look ___ the flight status before heading to the airport.", correct:"up", distractors:["into","over","after"], ex:"look up 表示「查詢資料」。"},
  {id:83, type:"phrase", cat:"daily", text:"I ___ into an old friend at the supermarket yesterday.", correct:"ran", distractors:["hit","fell","came"], ex:"run into someone 表示「偶然遇到某人」。"},
  {id:84, type:"phrase", cat:"travel", text:"Let's ___ along with the locals — they're really friendly here.", correct:"get", distractors:["come","hold","keep"], ex:"get along with 表示「與…相處融洽」。"},
  {id:85, type:"phrase", cat:"daily", text:"Could we ___ off the meeting until next week? I'm not ready.", correct:"put", distractors:["take","set","turn"], ex:"put off 表示「延後、拖延」。"},
  {id:86, type:"phrase", cat:"travel", text:"Don't ___ up on learning a few local phrases — it really helps.", correct:"give", distractors:["put","take","break"], ex:"give up on 表示「放棄」。"},
  {id:87, type:"phrase", cat:"daily", text:"I ___ across this great article while researching for work.", correct:"came", distractors:["went","got","looked"], ex:"come across 表示「偶然發現」。"},
  {id:88, type:"phrase", cat:"travel", text:"She really ___ after her mother — same smile and everything.", correct:"takes", distractors:["looks","gets","goes"], ex:"take after 表示「（外貌或個性）像家人」。"},
  {id:89, type:"phrase", cat:"daily", text:"He didn't ___ up to the party, so we left without him.", correct:"show", distractors:["stand","hold","keep"], ex:"show up 表示「出現、到場」。"},
  {id:90, type:"phrase", cat:"travel", text:"Our rental car ___ down in the middle of nowhere.", correct:"broke", distractors:["fell","ran","gave"], ex:"break down 表示「（車輛、機器）故障」。"},
  {id:91, type:"phrase", cat:"daily", text:"Take your time — there's no rush, we can ___ out the details later.", correct:"figure", distractors:["turn","set","bring"], ex:"figure out 表示「想出、弄清楚」。"},
  {id:92, type:"phrase", cat:"travel", text:"Our guide ___ up an interesting story about the old town's history.", correct:"brought", distractors:["took","gave","held"], ex:"bring up 表示「提起（話題）」。"},
  {id:93, type:"phrase", cat:"daily", text:"I had to ___ down the job offer — the salary was too low.", correct:"turn", distractors:["put","take","break"], ex:"turn down 表示「拒絕」。"},
  {id:94, type:"phrase", cat:"travel", text:"Could you ___ me up from the airport around 9 p.m.?", correct:"pick", distractors:["take","get","bring"], ex:"pick someone up 表示「去接某人」。"},
  {id:95, type:"phrase", cat:"daily", text:"Feel free to ___ by anytime — we're usually home in the evenings.", correct:"drop", distractors:["fall","step","set"], ex:"drop by 表示「順道拜訪」。"},
  {id:96, type:"phrase", cat:"travel", text:"It took her a while to ___ over the jet lag.", correct:"get", distractors:["come","go","break"], ex:"get over 表示「克服、恢復」。"},
  {id:97, type:"phrase", cat:"daily", text:"___ on a second, I just need to grab my keys.", correct:"Hold", distractors:["Keep","Stay","Set"], ex:"Hold on (a second) 是口語常用語，表示「稍等一下」。"},
  {id:98, type:"phrase", cat:"travel", text:"We decided to ___ on with our trip despite the rain.", correct:"carry", distractors:["bring","take","hold"], ex:"carry on (with) 表示「繼續進行」。"},
  {id:99, type:"phrase", cat:"daily", text:"If we're not careful with spending, we might ___ up broke by the end of the month.", correct:"end", distractors:["turn","bring","fall"], ex:"end up 表示「最終演變成某種結果」。"},
  {id:100, type:"phrase", cat:"travel", text:"You can always ___ on me if you need help with directions.", correct:"count", distractors:["focus","insist","agree"], ex:"count on 表示「依靠、信賴」。"},
  {id:101, type:"phrase", cat:"daily", text:"I'll ___ with this problem first thing tomorrow morning.", correct:"deal", distractors:["go","come","handle"], ex:"deal with 表示「處理」。"},
  {id:102, type:"phrase", cat:"travel", text:"It took the whole team a week to ___ up with a new itinerary.", correct:"come", distractors:["bring","get","make"], ex:"come up with 表示「想出（點子、方案）」。"},
  {id:103, type:"phrase", cat:"daily", text:"She's ___ through a really tough time at work lately.", correct:"going", distractors:["passing","running","coming"], ex:"go through 表示「經歷（困難）」。"},
  {id:104, type:"phrase", cat:"travel", text:"He felt dizzy and almost ___ out from the heat.", correct:"passed", distractors:["fell","gave","broke"], ex:"pass out 表示「昏倒」。"},
  {id:105, type:"phrase", cat:"daily", text:"We're planning to ___ off early to beat the morning traffic.", correct:"set", distractors:["take","turn","pull"], ex:"set off 表示「出發」。"},
  {id:106, type:"phrase", cat:"travel", text:"The driver had to ___ over because of the heavy fog.", correct:"pull", distractors:["set","get","turn"], ex:"pull over 表示「把車停到路邊」。"},
  {id:107, type:"phrase", cat:"daily", text:"The plane is scheduled to ___ off at 6 a.m. sharp.", correct:"take", distractors:["set","pull","get"], ex:"take off 表示飛機「起飛」。"},
  {id:108, type:"phrase", cat:"travel", text:"Don't forget to ___ off at the next stop — it's our station.", correct:"get", distractors:["pull","take","run"], ex:"get off 表示「下車」。"},
  {id:109, type:"phrase", cat:"daily", text:"We need to ___ on the next bus if we want to make it on time.", correct:"get", distractors:["pull","take","set"], ex:"get on 表示「上車、搭乘」。"},
  {id:110, type:"phrase", cat:"travel", text:"We're about to ___ out of cash — let's find an ATM.", correct:"run", distractors:["get","pull","go"], ex:"run out of 表示「用完、耗盡」。"},
  {id:111, type:"phrase", cat:"daily", text:"Could you ___ after my plants while I'm away?", correct:"look", distractors:["take","get","keep"], ex:"look after 表示「照顧」。"},
  {id:112, type:"phrase", cat:"travel", text:"What does this abbreviation on the ticket ___ for?", correct:"stand", distractors:["mean","look","go"], ex:"stand for 表示「代表、象徵」。"},
  {id:113, type:"phrase", cat:"daily", text:"Make sure to ___ up your files before the system update.", correct:"back", distractors:["set","pull","look"], ex:"back up 表示「備份」。"},
  {id:114, type:"phrase", cat:"travel", text:"The airline had to ___ off the flight due to the storm.", correct:"call", distractors:["set","turn","run"], ex:"call off 表示「取消」。"},
  {id:115, type:"phrase", cat:"daily", text:"Let me ___ you around the office before you start work.", correct:"show", distractors:["bring","set","look"], ex:"show someone around 表示「帶某人參觀」。"},
  {id:116, type:"phrase", cat:"travel", text:"A few of us went to the airport to ___ her off before her flight.", correct:"see", distractors:["take","bring","set"], ex:"see someone off 表示「為某人送行」。"},
  {id:117, type:"phrase", cat:"daily", text:"The pain medicine should ___ off in a few hours.", correct:"wear", distractors:["fade","run","die"], ex:"wear off 表示「（藥效、感覺）逐漸消退」。"},
  {id:118, type:"phrase", cat:"travel", text:"We decided to ___ to our original plan instead of changing the route.", correct:"stick", distractors:["go","stay","set"], ex:"stick to 表示「堅持、依照」。"},
  {id:119, type:"phrase", cat:"daily", text:"I need to ___ up on some sleep this weekend.", correct:"catch", distractors:["get","make","take"], ex:"catch up on 表示「補足（睡眠、進度等）」。"},
  {id:120, type:"phrase", cat:"travel", text:"After years of traveling, they finally decided to ___ down in one place.", correct:"settle", distractors:["set","stay","calm"], ex:"settle down 表示「安定下來、定居」。"},

  // ---------- Vocab batch (121-150) ----------
  {id:121, type:"vocab", cat:"daily", text:"Loud music can really ___ your ability to concentrate.", correct:"affect", distractors:["effect","effort","afford"], ex:"affect 是動詞「影響」，effect 通常作名詞「效果」，兩字常被搞混。"},
  {id:122, type:"vocab", cat:"travel", text:"Could you ___ me your phone charger for a few minutes?", correct:"lend", distractors:["borrow","rent","hire"], ex:"lend 是「借出」，borrow 是「借入」，方向相反，常被混用。"},
  {id:123, type:"vocab", cat:"daily", text:"I need to ___ my brother that I'll be late.", correct:"tell", distractors:["say","speak","talk"], ex:"tell 後面直接加人（tell + 人），say 不能直接加人。"},
  {id:124, type:"vocab", cat:"travel", text:"This neighborhood has several good restaurants within walking ___.", correct:"distance", distractors:["length","range","scope"], ex:"walking distance 是固定搭配，表示「步行可達的距離」。"},
  {id:125, type:"vocab", cat:"daily", text:"He's a very ___ person — always thinking about how others feel.", correct:"considerate", distractors:["considerable","considering","consideration"], ex:"considerate 表示「體貼的」，considerable 表示「相當大的（數量）」，兩字常混淆。"},
  {id:126, type:"vocab", cat:"travel", text:"Make sure you keep your ___ — it's needed for re-entry.", correct:"receipt", distractors:["recipe","reception","receive"], ex:"receipt（收據）與 recipe（食譜）拼字相近但意思完全不同。"},
  {id:127, type:"vocab", cat:"daily", text:"The new policy will ___ a significant impact on small businesses.", correct:"have", distractors:["do","make","take"], ex:"have an impact/effect on 是固定搭配，不能用 do / make / take 替換。"},
  {id:128, type:"vocab", cat:"travel", text:"We should exchange some money before the ___ rate changes.", correct:"exchange", distractors:["change","switch","trade"], ex:"exchange rate 是「匯率」的固定用語。"},
  {id:129, type:"vocab", cat:"daily", text:"I really ___ your help with the move last weekend.", correct:"appreciate", distractors:["thank","grateful","appreciation"], ex:"appreciate 是及物動詞，直接接受詞；thank 通常接人，grateful 是形容詞。"},
  {id:130, type:"vocab", cat:"travel", text:"We booked an ___ tour, so meals and activities are all covered.", correct:"all-inclusive", distractors:["all-included","all-inclusion","inclusive all"], ex:"all-inclusive 是固定用語，表示「包套全包式」。"},
  {id:131, type:"vocab", cat:"daily", text:"Please ___ the form and return it by Friday.", correct:"complete", distractors:["compete","complement","comply"], ex:"complete（填寫完成）與 compete（競爭）拼字相似但意思不同。"},
  {id:132, type:"vocab", cat:"travel", text:"The flight was delayed due to a technical ___.", correct:"issue", distractors:["issued","issuing","issuance"], ex:"issue 在此作名詞，表示「問題」。"},
  {id:133, type:"vocab", cat:"daily", text:"She gave a really ___ speech at the wedding.", correct:"touching", distractors:["touched","touch","touchy"], ex:"touching 表示「令人感動的」，touched 表示「（人）被感動的」，描述事物用 touching。"},
  {id:134, type:"vocab", cat:"travel", text:"Could you point out our hotel on the ___?", correct:"map", distractors:["plan","chart","scheme"], ex:"map 指地理地圖，plan 通常指建築平面圖或計畫。"},
  {id:135, type:"vocab", cat:"daily", text:"His explanation was so ___ that nobody understood it.", correct:"confusing", distractors:["confused","confuse","confusion"], ex:"confusing 描述「令人困惑的事物」，confused 描述「（人）感到困惑」。"},
  {id:136, type:"vocab", cat:"travel", text:"We need to ___ our flight at least 24 hours in advance.", correct:"check in for", distractors:["check in to","check out of","check on"], ex:"check in for a flight 是固定用法，表示「辦理登機手續」。"},
  {id:137, type:"vocab", cat:"daily", text:"I can't ___ the difference between these two shades of blue.", correct:"tell", distractors:["say","speak","know"], ex:"tell the difference 是固定搭配，表示「分辨出差異」。"},
  {id:138, type:"vocab", cat:"travel", text:"The hotel staff were incredibly ___ throughout our stay.", correct:"hospitable", distractors:["hospital","hospitalize","hospitality"], ex:"hospitable 是形容詞「好客的」，與 hospital（醫院）拼字相近但無關。"},
  {id:139, type:"vocab", cat:"daily", text:"It's important to stay ___ during long flights.", correct:"hydrated", distractors:["hydrate","hydration","hydrating"], ex:"stay hydrated 是固定片語，表示「保持水分充足」，hydrated 為形容詞用法。"},
  {id:140, type:"vocab", cat:"travel", text:"The museum is closed on ___ — plan your visit accordingly.", correct:"public holidays", distractors:["public holiday","publics holidays","public's holidays"], ex:"public holidays 為複數型態，指「國定假日」。"},
  {id:141, type:"vocab", cat:"daily", text:"He has a strong ___ for languages — he picks them up so fast.", correct:"aptitude", distractors:["attitude","altitude","aptly"], ex:"aptitude（天賦、資質）與 attitude（態度）拼字相近但意義不同。"},
  {id:142, type:"vocab", cat:"travel", text:"Don't forget to bring a universal power ___ for your devices.", correct:"adapter", distractors:["adopter","adaptor's","adapt"], ex:"adapter 指「轉接頭」，與 adopt（領養）字根不同，拼寫須留意。"},
  {id:143, type:"vocab", cat:"daily", text:"The meeting has been moved to a ___ time.", correct:"later", distractors:["latter","late","lately"], ex:"later 表示「較晚的（時間）」，latter 表示「後者」，常被混淆。"},
  {id:144, type:"vocab", cat:"travel", text:"There were ___ tourists than usual because of the off-season.", correct:"fewer", distractors:["less","little","few"], ex:"tourists 是可數名詞，須用 fewer，less 用於不可數名詞。"},
  {id:145, type:"vocab", cat:"daily", text:"The two reports are ___ identical, with only minor differences.", correct:"virtually", distractors:["virtual","virtue","virtuous"], ex:"virtually 是副詞，表示「幾乎、實際上」。"},
  {id:146, type:"vocab", cat:"travel", text:"Local customs ___ from region to region, so do some research first.", correct:"vary", distractors:["very","variety","variation"], ex:"vary 是動詞「不同、變化」，很容易與 very 拼字混淆。"},
  {id:147, type:"vocab", cat:"daily", text:"I'd like to ___ a complaint about the noise next door.", correct:"file", distractors:["fill","take","do"], ex:"file a complaint 是固定搭配，表示「提出投訴」。"},
  {id:148, type:"vocab", cat:"travel", text:"The view from the summit was absolutely ___.", correct:"breathtaking", distractors:["breathless","breathing","breath"], ex:"breathtaking 表示「令人屏息的、壯麗的」。"},
  {id:149, type:"vocab", cat:"daily", text:"Please keep your voice down — the baby is ___ asleep.", correct:"sound", distractors:["heavy","strong","deeply"], ex:"sound asleep 是固定片語，表示「熟睡」。"},
  {id:150, type:"vocab", cat:"travel", text:"The ferry departs ___ schedule every hour.", correct:"on", distractors:["in","by","at"], ex:"on schedule 表示「準時、按照時刻表」。"},

  // ---------- Grammar batch (151-270) ----------
  {id:151, type:"grammar", cat:"daily", text:"By this time next year, I ___ my degree.", correct:"will have finished", distractors:["will finish","have finished","finished"], ex:"未來完成式表示「在未來某時間點之前完成」。"},
  {id:152, type:"grammar", cat:"travel", text:"We ___ to Japan three times before, so we know the routine.", correct:"have been", distractors:["had been","were","have gone"], ex:"have been to 表示「去過某地（已經回來）」，have gone to 則表示「人還在那裡」，重複造訪要用 have been。"},
  {id:153, type:"grammar", cat:"daily", text:"I'd love to come, but I ___ work late tonight.", correct:"have to", distractors:["must to","should to","ought"], ex:"must、should 後面不加 to，have to 才需要加 to。"},
  {id:154, type:"grammar", cat:"travel", text:"The hotel is said ___ over a hundred years old.", correct:"to be", distractors:["being","be","been"], ex:"be said to V 是常見句型，表示「據說…」。"},
  {id:155, type:"grammar", cat:"daily", text:"I'd sooner stay home than ___ out in this weather.", correct:"go", distractors:["going","went","to go"], ex:"would sooner + 原形動詞 than + 原形動詞，表示「寧願…也不要…」。"},
  {id:156, type:"grammar", cat:"travel", text:"We were advised ___ travel insurance before the trip.", correct:"to get", distractors:["getting","get","got"], ex:"advise someone to V 的被動式為 be advised to V。"},
  {id:157, type:"grammar", cat:"daily", text:"He denied ___ anything about the surprise party.", correct:"knowing", distractors:["to know","know","knew"], ex:"deny + Ving，否認某事用動名詞。"},
  {id:158, type:"grammar", cat:"travel", text:"It's worth ___ a little extra for a direct flight.", correct:"paying", distractors:["to pay","pay","paid"], ex:"it's worth + Ving，表示「值得做…」。"},
  {id:159, type:"grammar", cat:"daily", text:"I'd love to, but I'm not ___ enough to commit to weekly meetings.", correct:"free", distractors:["freely","freedom","freeing"], ex:"be + 形容詞 + enough to V，free 是形容詞。"},
  {id:160, type:"grammar", cat:"travel", text:"We arrived ___ to catch the last bus.", correct:"just in time", distractors:["just on time","just at time","right in time"], ex:"just in time 表示「剛好趕上」，是固定片語。"},
  {id:161, type:"grammar", cat:"daily", text:"The longer the meeting went on, ___ everyone became.", correct:"the more restless", distractors:["more restless","the most restless","much restless"], ex:"the + 比較級, the + 比較級 句型結構需對稱。"},
  {id:162, type:"grammar", cat:"travel", text:"Were it not for the delay, we ___ on time.", correct:"would have arrived", distractors:["would arrive","will arrive","arrived"], ex:"Were it not for 是與過去事實相反的假設句倒裝形式，主句用 would have + p.p.。"},
  {id:163, type:"grammar", cat:"daily", text:"She's not as outgoing as she ___ to be.", correct:"used", distractors:["use","is used","was using"], ex:"used to + 原形動詞，表示「過去曾經如此（現在不是）」。"},
  {id:164, type:"grammar", cat:"travel", text:"Make sure the suitcase ___ before you check it in.", correct:"is properly closed", distractors:["properly closed","closes properly","closing properly"], ex:"需要完整的 be 動詞 + 過去分詞結構，表示行李「被關好」的狀態。"},
  {id:165, type:"grammar", cat:"daily", text:"I'd rather we ___ this discussion in private.", correct:"had", distractors:["have","will have","having"], ex:"would rather + 主詞 + 過去式動詞，表達對現在/未來的偏好建議。"},
  {id:166, type:"grammar", cat:"travel", text:"No sooner ___ the plane landed than passengers started unbuckling their seatbelts.", correct:"had", distractors:["did","has","was"], ex:"No sooner had + 主詞 + p.p. + than，倒裝句表示「一…就…」。"},
  {id:167, type:"grammar", cat:"daily", text:"I can't seem to get used ___ this new schedule.", correct:"to", distractors:["with","for","at"], ex:"get used to + N/Ving，to 是介系詞。"},
  {id:168, type:"grammar", cat:"travel", text:"This is the only hotel ___ rooms are still available.", correct:"whose", distractors:["which","that","who"], ex:"whose 可用於指物，表示「…的」所有格關係代名詞。"},
  {id:169, type:"grammar", cat:"daily", text:"She apologized for not ___ in touch sooner.", correct:"keeping", distractors:["to keep","keep","kept"], ex:"apologize for + Ving。"},
  {id:170, type:"grammar", cat:"travel", text:"We should leave ___ to avoid the afternoon heat.", correct:"earlier rather than later", distractors:["early than late","more early","earlier than late"], ex:"earlier rather than later 是固定用語，表示「寧可早一點」。"},
  {id:171, type:"grammar", cat:"daily", text:"I'd prefer ___ at home tonight rather than going out.", correct:"to stay", distractors:["staying","stay","stayed"], ex:"would prefer to V，表示偏好做某事。"},
  {id:172, type:"grammar", cat:"travel", text:"By the time the tour ends, we ___ at least ten temples.", correct:"will have visited", distractors:["will visit","visited","have visited"], ex:"未來完成式，表示在未來某時間點之前已完成。"},
  {id:173, type:"grammar", cat:"daily", text:"It is rumored that the company ___ several new branches next year.", correct:"will open", distractors:["opens","is opening","open"], ex:"表示對未來的預測，用 will + 原形動詞。"},
  {id:174, type:"grammar", cat:"travel", text:"Had we checked the forecast, we ___ better prepared.", correct:"would have been", distractors:["would be","will be","were"], ex:"與過去事實相反的假設句倒裝形式，主句用 would have + p.p.。"},
  {id:175, type:"grammar", cat:"daily", text:"I'm not entirely sure, but I think the keys might ___ in the car.", correct:"be", distractors:["being","been","to be"], ex:"情態助動詞 might 後面接原形動詞。"},
  {id:176, type:"grammar", cat:"travel", text:"Whichever route we ___, it will take at least two hours.", correct:"take", distractors:["took","taken","will take"], ex:"複合關係代名詞 whichever 引導的子句，描述一般情況用現在式。"},
  {id:177, type:"grammar", cat:"daily", text:"The more I think about it, ___ I feel about quitting.", correct:"the worse", distractors:["worse","the worst","much worse"], ex:"the + 比較級, the + 比較級 句型。"},
  {id:178, type:"grammar", cat:"travel", text:"All things considered, the trip ___ pretty smoothly.", correct:"went", distractors:["goes","has gone","go"], ex:"all things considered 為插入語，描述過去事件用過去式 went。"},
  {id:179, type:"grammar", cat:"daily", text:"I really must get ___ this report before the weekend.", correct:"around to", distractors:["round at","over to","up to"], ex:"get around to (Ving/N) 表示「終於抽空處理」。"},
  {id:180, type:"grammar", cat:"travel", text:"It wasn't until we landed ___ we realized we'd left the umbrella on the plane.", correct:"that", distractors:["when","then","which"], ex:"It wasn't until... that... 是強調句型，表示「直到…才…」。"},
  {id:181, type:"grammar", cat:"daily", text:"I'd just as soon ___ home than go to another loud party.", correct:"stay", distractors:["staying","stayed","to stay"], ex:"would just as soon + 原形動詞，表示「寧可…」。"},
  {id:182, type:"grammar", cat:"travel", text:"Under no circumstances ___ you leave your luggage unattended.", correct:"should", distractors:["you should","shall","you shall"], ex:"Under no circumstances 放句首要倒裝，助動詞提前。"},
  {id:183, type:"grammar", cat:"daily", text:"I wasn't aware that the deadline ___ moved up.", correct:"had been", distractors:["was","has been","is"], ex:"主要子句過去式 wasn't aware，依時態一致原則，子句用過去完成式。"},
  {id:184, type:"grammar", cat:"travel", text:"Only after we boarded ___ realize we were on the wrong flight.", correct:"did we", distractors:["we did","we were","were we"], ex:"Only after... 放句首要倒裝，助動詞+主詞提前。"},
  {id:185, type:"grammar", cat:"daily", text:"I'd appreciate ___ told in advance next time.", correct:"being", distractors:["to being","be","to be"], ex:"appreciate + Ving，此處是被動動名詞 being told。"},
  {id:186, type:"grammar", cat:"travel", text:"The sooner we book, ___ the tickets will be.", correct:"the cheaper", distractors:["cheaper","the cheapest","much cheaper"], ex:"the + 比較級, the + 比較級 句型。"},
  {id:187, type:"grammar", cat:"daily", text:"He acted as though nothing ___ happened.", correct:"had", distractors:["has","did","was"], ex:"as though + 過去完成式，表示與過去事實相反的假設。"},
  {id:188, type:"grammar", cat:"travel", text:"We're not allowed to bring liquids over 100ml, ___ we?", correct:"are", distractors:["aren't","don't","do"], ex:"附加問句：前面是否定句 not allowed，附加問句要用肯定 are we。"},
  {id:189, type:"grammar", cat:"daily", text:"I'd have called you earlier had I ___ your number.", correct:"had", distractors:["have","has","having"], ex:"與過去事實相反假設句倒裝形式：Had I had your number = If I had had your number。"},
  {id:190, type:"grammar", cat:"travel", text:"It's about time we ___ for the airport.", correct:"left", distractors:["leave","will leave","are leaving"], ex:"it's about time + 子句用過去式，表示「該是…的時候了」。"},
  {id:191, type:"grammar", cat:"daily", text:"I object to ___ treated like a child.", correct:"being", distractors:["be","to being","to be"], ex:"object to + Ving，介系詞 to 後接動名詞。"},
  {id:192, type:"grammar", cat:"travel", text:"We'd been driving for hours before we ___ that we were lost.", correct:"realized", distractors:["realize","have realized","were realizing"], ex:"過去完成進行式之後接續發生的單一動作要用過去簡單式 realized。"},
  {id:193, type:"grammar", cat:"daily", text:"I'm afraid I won't be able to make it, ___ something comes up.", correct:"unless", distractors:["if","whether","in case"], ex:"unless 表示「除非」，等同 if...not。"},
  {id:194, type:"grammar", cat:"travel", text:"___ you need anything during the flight, just press the call button.", correct:"Should", distractors:["Would","Were","Did"], ex:"Should you + 原形動詞 是 If you should 的倒裝省略形式，常用於正式語氣。"},
  {id:195, type:"grammar", cat:"daily", text:"I'd rather not say what happened, if you ___ mind.", correct:"don't", distractors:["didn't","won't","aren't"], ex:"if you don't mind 是禮貌用語，表示「如果你不介意的話」。"},
  {id:196, type:"grammar", cat:"travel", text:"The flight was so delayed ___ we missed our connection entirely.", correct:"that", distractors:["so","as","which"], ex:"so + 形容詞/副詞 + that 子句，表示「如此…以致於…」。"},
  {id:197, type:"grammar", cat:"daily", text:"I haven't the faintest idea ___ he's talking about.", correct:"what", distractors:["that","which","who"], ex:"受詞子句的疑問詞用 what，表示「他在說什麼」。"},
  {id:198, type:"grammar", cat:"travel", text:"We'll need to leave at dawn, ___ we want to catch the sunrise tour.", correct:"if", distractors:["unless","whether","although"], ex:"if 引導條件句，表示「如果」。"},
  {id:199, type:"grammar", cat:"daily", text:"I can't quite put my finger on what's ___ me about this plan.", correct:"bothering", distractors:["bother","bothered","to bother"], ex:"bothering 為現在分詞作形容詞用法，描述「令人困擾的」。"},
  {id:200, type:"grammar", cat:"travel", text:"We were the last ___ board the plane.", correct:"to", distractors:["that","who","for"], ex:"the last + to V，表示「最後…的人」。"},
  {id:201, type:"grammar", cat:"daily", text:"I'd be lying if I ___ I wasn't nervous.", correct:"said", distractors:["say","would say","had said"], ex:"假設語氣中，與現在事實相反用過去式 said。"},
  {id:202, type:"grammar", cat:"travel", text:"We're hoping the weather holds up, ___ the forecast says otherwise.", correct:"even though", distractors:["even if","despite","in spite"], ex:"even though + 子句，表示「儘管（事實如此）」；even if 則表示「即使（假設情況）」。"},
  {id:203, type:"grammar", cat:"daily", text:"I'd just gotten home when the phone ___ rang.", correct:"suddenly", distractors:["sudden","suddenness","suddenly to"], ex:"suddenly 是副詞，修飾動詞 rang。"},
  {id:204, type:"grammar", cat:"travel", text:"We must've taken a wrong turn somewhere — this ___ be the right street.", correct:"can't", distractors:["mustn't","shouldn't","won't"], ex:"can't be 表示「不可能是」，用於對現在情況的強烈否定推測。"},
  {id:205, type:"grammar", cat:"daily", text:"You ___ have told me earlier — now we're going to be late.", correct:"should", distractors:["must","could","would"], ex:"should have + p.p. 表示「（過去）本該做卻沒做」的責備語氣。"},
  {id:206, type:"grammar", cat:"travel", text:"She must ___ left already; her bags are gone.", correct:"have", distractors:["had","has","be"], ex:"must have + p.p. 表示對過去情況的強烈推測。"},
  {id:207, type:"grammar", cat:"daily", text:"I needn't ___ worried — everything turned out fine.", correct:"have", distractors:["had","has","be"], ex:"needn't have + p.p. 表示「（過去）不必做卻做了」。"},
  {id:208, type:"grammar", cat:"travel", text:"You ___ have booked in advance — walk-ins aren't accepted here.", correct:"should", distractors:["needn't","mustn't","can't"], ex:"should have + p.p. 表示對過去未做之事的建議或責備。"},
  {id:209, type:"grammar", cat:"daily", text:"He can't have ___ the email — he would have replied by now.", correct:"seen", distractors:["see","saw","seeing"], ex:"can't have + p.p. 表示「不可能已經…」的推測。"},
  {id:210, type:"grammar", cat:"travel", text:"They might have ___ the flight by now, given the time difference.", correct:"boarded", distractors:["board","boarding","boards"], ex:"might have + p.p. 表示對過去情況不確定的推測。"},
  {id:211, type:"grammar", cat:"daily", text:"I wish you ___ stop interrupting me.", correct:"would", distractors:["will","could","should"], ex:"wish + 主詞 + would，用於表達對他人行為的不滿或希望改變。"},
  {id:212, type:"grammar", cat:"travel", text:"If only we ___ booked the earlier flight.", correct:"had", distractors:["have","would have","did"], ex:"if only + 過去完成式，表達對過去的遺憾。"},
  {id:213, type:"grammar", cat:"daily", text:"It's time you ___ a decision — we can't wait any longer.", correct:"made", distractors:["make","will make","are making"], ex:"it's time + 主詞 + 過去式，表示「該是…的時候了」。"},
  {id:214, type:"grammar", cat:"travel", text:"Suppose we ___ lost — what would you do?", correct:"got", distractors:["get","will get","have got"], ex:"suppose + 過去式，表示假設情境（與現在事實相反）。"},
  {id:215, type:"grammar", cat:"daily", text:"I'd just as well ___ this myself instead of waiting for help.", correct:"do", distractors:["doing","did","to do"], ex:"would just as well + 原形動詞，表示「不如…」。"},
  {id:216, type:"grammar", cat:"travel", text:"It's high time the airline ___ better compensation for delays.", correct:"offered", distractors:["offers","will offer","is offering"], ex:"it's high time + 子句用過去式，表示「早該…」。"},
  {id:217, type:"grammar", cat:"daily", text:"Even if I ___ the time, I wouldn't go to that event.", correct:"had", distractors:["have","will have","having"], ex:"第二類條件句，與現在事實相反的假設，子句用過去式。"},
  {id:218, type:"grammar", cat:"travel", text:"If the airline ___ the flight, we'd have lost our connection.", correct:"hadn't delayed", distractors:["didn't delay","wouldn't delay","doesn't delay"], ex:"與過去事實相反的假設句，子句用過去完成式 hadn't delayed。"},
  {id:219, type:"grammar", cat:"daily", text:"She talks as if she ___ everything about the topic.", correct:"knew", distractors:["knows","had known","know"], ex:"as if + 過去式，表示與現在事實不符的假設語氣。"},
  {id:220, type:"grammar", cat:"travel", text:"I'd have taken photos ___ I'd remembered to charge my phone.", correct:"if", distractors:["unless","whether","when"], ex:"if 引導與過去事實相反的條件句。"},
  {id:221, type:"grammar", cat:"daily", text:"Not until she explained it twice ___ understand.", correct:"did I", distractors:["I did","had I","I had"], ex:"Not until... 放句首要倒裝，助動詞+主詞提前。"},
  {id:222, type:"grammar", cat:"travel", text:"So delayed was the flight ___ passengers began demanding refunds.", correct:"that", distractors:["which","as","so"], ex:"So + 形容詞 + be 動詞 + 主詞 + that，是倒裝強調句型。"},
  {id:223, type:"grammar", cat:"daily", text:"Little ___ that the meeting would run three hours over.", correct:"did we know", distractors:["we knew","we did know","did we knew"], ex:"Little + 倒裝句，表示「完全沒料到」。"},
  {id:224, type:"grammar", cat:"travel", text:"Such was the crowd at the gate ___ we almost missed boarding.", correct:"that", distractors:["which","as","so"], ex:"Such + be 動詞 + 主詞 + that，倒裝強調句型，表示「如此…以致於…」。"},
  {id:225, type:"grammar", cat:"daily", text:"Were she here, she ___ exactly what to do.", correct:"would know", distractors:["will know","knows","would have known"], ex:"Were she here 是 If she were here 的倒裝省略形式，第二類條件句。"},
  {id:226, type:"grammar", cat:"travel", text:"Should the flight be cancelled, passengers ___ a full refund.", correct:"will receive", distractors:["receive","received","would receive"], ex:"Should + 主詞 + 原形動詞 是 If 引導的第一類條件句倒裝形式，主句用 will。"},
  {id:227, type:"grammar", cat:"daily", text:"I'd sooner you ___ me the truth than make excuses.", correct:"told", distractors:["tell","will tell","had told"], ex:"would sooner + 主詞 + 過去式動詞，表達對他人行為的偏好。"},
  {id:228, type:"grammar", cat:"travel", text:"Given that the weather ___, we should reconsider the hike.", correct:"is so unpredictable", distractors:["so unpredictable is","being so unpredictable","unpredictable is so"], ex:"given that + 子句，表示「考慮到…」，子句語序為一般直述句。"},
  {id:229, type:"grammar", cat:"daily", text:"I'm not one ___ complain, but this service has been terrible.", correct:"to", distractors:["for","of","that"], ex:"not one to V，表示「不是會做某事的人」。"},
  {id:230, type:"grammar", cat:"travel", text:"As far as I'm aware, the museum ___ open on public holidays.", correct:"remains", distractors:["remained","has remained","remaining"], ex:"as far as I'm aware 表達現在的認知，主要子句用現在式 remains。"},
  {id:231, type:"grammar", cat:"daily", text:"For all his experience, he still ___ nervous before presentations.", correct:"gets", distractors:["got","is getting","has got"], ex:"for all + N，表示「儘管」，描述一般習慣用現在式。"},
  {id:232, type:"grammar", cat:"travel", text:"Much as I'd like to stay longer, I ___ to get back for work.", correct:"need", distractors:["needed","will need","am needing"], ex:"much as + 子句，表示「儘管很想…」，但仍描述現況用現在式。"},
  {id:233, type:"grammar", cat:"daily", text:"Try as I ___, I couldn't fix the printer myself.", correct:"might", distractors:["may","would","could"], ex:"try as + 主詞 + might 是固定讓步句型，表示「儘管努力嘗試」。"},
  {id:234, type:"grammar", cat:"travel", text:"___ what may, we're still going on this trip.", correct:"Come", distractors:["Comes","Came","Coming"], ex:"Come what may 是固定片語（假設語氣），表示「無論發生什麼事」。"},
  {id:235, type:"grammar", cat:"daily", text:"___ that as it may, I still think we should apologize.", correct:"Be", distractors:["Is","Was","Being"], ex:"Be that as it may 是固定讓步片語，表示「即便如此」。"},
  {id:236, type:"grammar", cat:"travel", text:"I'd as soon walk ___ wait for a taxi in this heat.", correct:"as", distractors:["than","that","like"], ex:"would as soon... as... 表示「寧願…也不要…」。"},
  {id:237, type:"grammar", cat:"daily", text:"What with the noise and the heat, I barely ___ any sleep.", correct:"got", distractors:["get","have got","was getting"], ex:"what with... 表示「由於…的緣故」，描述過去事件用過去式。"},
  {id:238, type:"grammar", cat:"travel", text:"It goes without saying ___ you should keep your passport safe.", correct:"that", distractors:["which","what","if"], ex:"it goes without saying that... 是固定句型，表示「不用說，當然…」。"},
  {id:239, type:"grammar", cat:"daily", text:"As luck would have it, the shop ___ closed early that day.", correct:"was", distractors:["is","has been","were"], ex:"as luck would have it 表示「碰巧」，描述過去事件用過去式。"},
  {id:240, type:"grammar", cat:"travel", text:"___ it up to me, I'd extend the trip by a week.", correct:"Were", distractors:["Is","Was","Being"], ex:"Were it up to me 是 If it were up to me 的倒裝省略形式。"},
  {id:241, type:"grammar", cat:"daily", text:"I'd ___ call that a fair trade — you got the better deal.", correct:"hardly", distractors:["hard","harder","hardly to"], ex:"hardly 是副詞，修飾動詞 call，表示「幾乎不能說是」。"},
  {id:242, type:"grammar", cat:"travel", text:"We've yet ___ decide where to go next year.", correct:"to", distractors:["for","at","of"], ex:"have yet to V，表示「尚未…」。"},
  {id:243, type:"grammar", cat:"daily", text:"I'd be the first ___ admit I was wrong.", correct:"to", distractors:["that","for","of"], ex:"the first + to V，表示「第一個（做某事）的人」。"},
  {id:244, type:"grammar", cat:"travel", text:"Little did the tourists know ___ the festival was cancelled.", correct:"that", distractors:["which","what","if"], ex:"Little did + 主詞 + 動詞 + that 子句，倒裝句後接 that 引導的受詞子句。"},
  {id:245, type:"grammar", cat:"daily", text:"I'd hate ___ think what would happen if we missed the deadline.", correct:"to", distractors:["for","that","of"], ex:"would hate to V，表示「不願去想…」。"},
  {id:246, type:"grammar", cat:"travel", text:"We've got every reason ___ believe the trip will go smoothly.", correct:"to", distractors:["for","of","that"], ex:"have reason to V，表示「有理由相信」。"},
  {id:247, type:"grammar", cat:"daily", text:"I'd be lying ___ I said I wasn't a little worried.", correct:"if", distractors:["that","when","unless"], ex:"if 引導與現在事實相反的條件句。"},
  {id:248, type:"grammar", cat:"travel", text:"We're under the impression ___ the museum closes at six.", correct:"that", distractors:["which","what","if"], ex:"under the impression that... 表示「以為、認為」，後接 that 子句。"},
  {id:249, type:"grammar", cat:"daily", text:"I'd be remiss ___ mention how much help you've been.", correct:"not to", distractors:["to not","not for","to"], ex:"would be remiss not to V，表示「如果不…就太失職了」。"},
  {id:250, type:"grammar", cat:"travel", text:"We're well aware ___ the risks involved in this kind of trip.", correct:"of", distractors:["for","to","with"], ex:"be aware of + N，表示「意識到」。"},
  {id:251, type:"grammar", cat:"daily", text:"I'd just as soon you ___ mention this to anyone.", correct:"didn't", distractors:["don't","wouldn't","won't"], ex:"would just as soon + 主詞 + 過去式動詞，表達對他人行為的偏好。"},
  {id:252, type:"grammar", cat:"travel", text:"Provided the weather cooperates, the hike ___ go ahead as scheduled.", correct:"will", distractors:["would","shall","might've"], ex:"provided that 引導條件句，子句現在式，主句用 will 表未來。"},
  {id:253, type:"grammar", cat:"daily", text:"I'd have ___ you'd know better by now.", correct:"thought", distractors:["think","thinking","thinks"], ex:"would have thought 表示「（原本）以為」，常用於表達意外或失望。"},
  {id:254, type:"grammar", cat:"travel", text:"We're not in a position ___ make that decision right now.", correct:"to", distractors:["for","of","that"], ex:"be in a position to V，表示「有能力/立場去做」。"},
  {id:255, type:"grammar", cat:"daily", text:"I'd be grateful ___ you could let me know in advance.", correct:"if", distractors:["that","when","for"], ex:"I'd be grateful if + 子句，是禮貌委婉的請求句型。"},
  {id:256, type:"grammar", cat:"travel", text:"We've reached the point ___ we need to make a final decision.", correct:"where", distractors:["which","that","when"], ex:"the point where... 表示「（事情發展到）…的地步」。"},
  {id:257, type:"grammar", cat:"daily", text:"I'd be surprised ___ he actually shows up on time.", correct:"if", distractors:["that","when","unless"], ex:"I'd be surprised if + 子句，表達對某事發生機率低的看法。"},
  {id:258, type:"grammar", cat:"travel", text:"We're counting on the fact ___ flights are usually cheaper midweek.", correct:"that", distractors:["which","what","if"], ex:"the fact that... 後接同位語子句，說明 fact 的具體內容。"},
  {id:259, type:"grammar", cat:"daily", text:"I'd be the last person ___ judge — I've made plenty of mistakes too.", correct:"to", distractors:["that","for","of"], ex:"the last person + to V，表示「最不該做某事的人」。"},
  {id:260, type:"grammar", cat:"travel", text:"We're inclined ___ believe the delay was caused by weather, not staffing.", correct:"to", distractors:["for","of","that"], ex:"be inclined to V，表示「傾向於」。"},
  {id:261, type:"grammar", cat:"daily", text:"I'd rather not say, if it's all ___ to you.", correct:"the same", distractors:["alike","equal","similar"], ex:"if it's all the same to you 是禮貌用語，表示「如果你不介意的話」。"},
  {id:262, type:"grammar", cat:"travel", text:"We're determined ___ make the most of this trip.", correct:"to", distractors:["for","of","that"], ex:"be determined to V，表示「下定決心」。"},
  {id:263, type:"grammar", cat:"daily", text:"I'd be happy ___ help, as long as it doesn't take too long.", correct:"to", distractors:["for","of","that"], ex:"be happy to V，表示「樂意做某事」。"},
  {id:264, type:"grammar", cat:"travel", text:"We're in no rush, so there's no need ___ hurry.", correct:"to", distractors:["for","of","that"], ex:"there's no need to V，表示「沒有必要做某事」。"},
  {id:265, type:"grammar", cat:"daily", text:"I'd think twice ___ making such a big decision so quickly.", correct:"before", distractors:["of","for","to"], ex:"think twice before + Ving，表示「在…之前要三思」。"},
  {id:266, type:"grammar", cat:"travel", text:"We're keen ___ explore the local markets while we're here.", correct:"to", distractors:["for","of","on"], ex:"be keen to V 表示「渴望、熱衷於」（注意 keen on 後面要接動名詞 Ving，與此句結構不同）。"},
  {id:267, type:"grammar", cat:"daily", text:"I'd be lying if I said this wasn't a little stressful — I'm ___ worried.", correct:"genuinely", distractors:["genuine","genuineness","generally"], ex:"genuinely 是副詞，修飾形容詞 worried。"},
  {id:268, type:"grammar", cat:"travel", text:"We're well within our rights ___ ask for a refund.", correct:"to", distractors:["for","of","that"], ex:"be within one's rights to V，表示「有權利做…」。"},
  {id:269, type:"grammar", cat:"daily", text:"I'd be remiss if I didn't ___ how much this means to me.", correct:"mention", distractors:["mentioning","mentioned","to mention"], ex:"if 子句中 didn't + 原形動詞，動詞用原形 mention。"},
  {id:270, type:"grammar", cat:"travel", text:"We're as ready as we'll ever ___ for this trip.", correct:"be", distractors:["being","been","are"], ex:"as...as we'll ever be 是固定用語，be 為原形動詞搭配助動詞 will。"},

  // ---------- Phrase batch (271-390) ----------
  {id:271, type:"phrase", cat:"daily", text:"It took a while, but they finally managed to ___ the problem out.", correct:"sort", distractors:["sift","settle","solve"], ex:"sort out 表示「解決、整理清楚」。"},
  {id:272, type:"phrase", cat:"travel", text:"The trip almost ___ through because of visa issues.", correct:"fell", distractors:["broke","gave","ran"], ex:"fall through 表示「（計畫）告吹、未能實現」。"},
  {id:273, type:"phrase", cat:"daily", text:"He always seems to ___ away with being late.", correct:"get", distractors:["run","go","come"], ex:"get away with 表示「逃過懲罰、僥倖不被追究」。"},
  {id:274, type:"phrase", cat:"travel", text:"Could you help me ___ out the cheapest way to get downtown?", correct:"work", distractors:["set","make","turn"], ex:"work out 表示「算出、想出（解決辦法）」。"},
  {id:275, type:"phrase", cat:"daily", text:"I don't want to ___ you down, but I can't make it tonight.", correct:"let", distractors:["put","turn","bring"], ex:"let someone down 表示「讓某人失望」。"},
  {id:276, type:"phrase", cat:"travel", text:"We need to ___ up early to catch the sunrise tour.", correct:"get", distractors:["set","stand","rise"], ex:"get up 表示「起床」。"},
  {id:277, type:"phrase", cat:"daily", text:"She finally ___ down to writing her thesis after months of procrastinating.", correct:"got", distractors:["set","put","turned"], ex:"get down to (Ving) 表示「開始認真處理」。"},
  {id:278, type:"phrase", cat:"travel", text:"The tour company had to ___ out a refund policy after complaints.", correct:"work", distractors:["sort","figure","make"], ex:"work out 在此表示「制定出（政策、方案）」。"},
  {id:279, type:"phrase", cat:"daily", text:"I really need to ___ up with my emails — I'm so behind.", correct:"catch", distractors:["keep","get","make"], ex:"catch up with 表示「趕上進度」。"},
  {id:280, type:"phrase", cat:"travel", text:"It's hard to ___ up with the pace of a guided tour group.", correct:"keep", distractors:["catch","get","hold"], ex:"keep up with 表示「跟上（速度、進度）」，與 catch up with（追上落後進度）略有不同。"},
  {id:281, type:"phrase", cat:"daily", text:"He tends to ___ down on people who didn't go to university.", correct:"look", distractors:["take","get","turn"], ex:"look down on 表示「看不起」。"},
  {id:282, type:"phrase", cat:"travel", text:"We managed to ___ off a last-minute hotel upgrade.", correct:"pull", distractors:["take","carry","set"], ex:"pull off 表示「成功做到（困難的事）」。"},
  {id:283, type:"phrase", cat:"daily", text:"Could you ___ down what she said? I want to remember it exactly.", correct:"write", distractors:["mark","drop","pull"], ex:"write down 表示「寫下來」。"},
  {id:284, type:"phrase", cat:"travel", text:"We're going to ___ out the old itinerary and start fresh.", correct:"throw", distractors:["take","cut","tear"], ex:"throw out 表示「丟棄、捨棄」。"},
  {id:285, type:"phrase", cat:"daily", text:"I need to ___ over my notes before the exam tomorrow.", correct:"go", distractors:["set","turn","bring"], ex:"go over 表示「複習、檢查一遍」。"},
  {id:286, type:"phrase", cat:"travel", text:"The airline agreed to ___ us up to business class.", correct:"bump", distractors:["pick","set","turn"], ex:"bump someone up 表示「（航空公司主動）升等」。"},
  {id:287, type:"phrase", cat:"daily", text:"Let's ___ this meeting short — I have another call in five minutes.", correct:"cut", distractors:["make","keep","turn"], ex:"cut something short 表示「提前結束」。"},
  {id:288, type:"phrase", cat:"travel", text:"Let's ___ up this tour with a visit to the night market.", correct:"wrap", distractors:["pack","close","shut"], ex:"wrap up 表示「結束、完成」。"},
  {id:289, type:"phrase", cat:"daily", text:"I'm trying to ___ into the habit of going to bed earlier.", correct:"get", distractors:["fall","make","turn"], ex:"get into the habit of 表示「養成…的習慣」。"},
  {id:290, type:"phrase", cat:"travel", text:"We wanted somewhere ___ the beaten path, away from the crowds.", correct:"off", distractors:["out","beyond","under"], ex:"off the beaten path 是固定片語，表示「人煙稀少、非熱門觀光路線」。"},
  {id:291, type:"phrase", cat:"daily", text:"He's always trying to ___ in on other people's conversations.", correct:"butt", distractors:["cut","jump","break"], ex:"butt in 表示「（不請自來地）插嘴」。"},
  {id:292, type:"phrase", cat:"travel", text:"We should ___ ahead and book the restaurant now before it fills up.", correct:"go", distractors:["set","get","push"], ex:"go ahead (and do something) 表示「就直接去做」。"},
  {id:293, type:"phrase", cat:"daily", text:"I can't ___ my head around why he'd quit such a good job.", correct:"wrap", distractors:["turn","get","put"], ex:"wrap one's head around 表示「理解、想通」。"},
  {id:294, type:"phrase", cat:"travel", text:"We need to ___ down our options before booking anything.", correct:"narrow", distractors:["cut","sort","turn"], ex:"narrow down 表示「縮小範圍」。"},
  {id:295, type:"phrase", cat:"daily", text:"She's been trying to ___ into the company for years — she finally got the job.", correct:"break", distractors:["get","cut","push"], ex:"break into (an industry/company) 表示「打入、成功進入」。"},
  {id:296, type:"phrase", cat:"travel", text:"The guide will ___ us through the safety procedures before we start diving.", correct:"walk", distractors:["talk","take","lead"], ex:"walk someone through 表示「詳細說明、帶領了解」。"},
  {id:297, type:"phrase", cat:"daily", text:"I think we should ___ this idea by the team before moving forward.", correct:"run", distractors:["walk","talk","take"], ex:"run something by someone 表示「徵詢某人的意見」。"},
  {id:298, type:"phrase", cat:"travel", text:"We're trying to ___ down the best time of year to visit.", correct:"pin", distractors:["track","mark","set"], ex:"pin down 表示「明確找出、確定」。"},
  {id:299, type:"phrase", cat:"daily", text:"He likes to ___ on about his travels — sometimes for hours.", correct:"go", distractors:["talk","run","carry"], ex:"go on (about something) 表示「滔滔不絕地說」。"},
  {id:300, type:"phrase", cat:"travel", text:"We should ___ in some free time for shopping during the trip.", correct:"build", distractors:["set","make","put"], ex:"build in 表示「（在計畫中）預留、安排」。"},
  {id:301, type:"phrase", cat:"daily", text:"It's important to ___ things through before making a big decision.", correct:"think", distractors:["work","talk","go"], ex:"think something through 表示「仔細想清楚」。"},
  {id:302, type:"phrase", cat:"travel", text:"We had to ___ up with the delay and just wait it out.", correct:"put", distractors:["keep","catch","deal"], ex:"put up with 表示「忍受」。"},
  {id:303, type:"phrase", cat:"daily", text:"I don't want to ___ in on your family time.", correct:"barge", distractors:["push","cut","break"], ex:"barge in (on) 表示「不請自來地打擾」。"},
  {id:304, type:"phrase", cat:"travel", text:"We're going to ___ up camp near the lake for the night.", correct:"set", distractors:["put","make","build"], ex:"set up camp 表示「紮營」。"},
  {id:305, type:"phrase", cat:"daily", text:"Let's not ___ into an argument over something this small.", correct:"get", distractors:["fall","go","come"], ex:"get into an argument 表示「捲入爭吵」。"},
  {id:306, type:"phrase", cat:"travel", text:"The local guide really ___ the history of the temple to life.", correct:"brought", distractors:["took","gave","held"], ex:"bring something to life 表示「使…生動起來」。"},
  {id:307, type:"phrase", cat:"daily", text:"I'm going to ___ it a night — I'm exhausted.", correct:"call", distractors:["make","take","turn"], ex:"call it a night 表示「今晚就到此為止、休息了」。"},
  {id:308, type:"phrase", cat:"travel", text:"We should ___ a move if we want to catch the ferry.", correct:"make", distractors:["take","get","do"], ex:"make a move 在此表示「該出發了」。"},
  {id:309, type:"phrase", cat:"daily", text:"He's always the one to ___ the ice at parties.", correct:"break", distractors:["cut","melt","clear"], ex:"break the ice 表示「打破僵局、緩和氣氛」。"},
  {id:310, type:"phrase", cat:"travel", text:"It really is a ___ of cake to get around this city by metro.", correct:"piece", distractors:["slice","bit","cut"], ex:"a piece of cake 表示「輕而易舉的事」。"},
  {id:311, type:"phrase", cat:"daily", text:"I think we finally ___ eye to eye on this.", correct:"see", distractors:["look","meet","get"], ex:"see eye to eye 表示「意見一致」。"},
  {id:312, type:"phrase", cat:"travel", text:"Don't ___ the boat — flights this cheap don't come around often.", correct:"miss", distractors:["lose","catch","sink"], ex:"miss the boat 表示「錯失良機」。"},
  {id:313, type:"phrase", cat:"daily", text:"I think it's time we ___ the bullet and just told him the truth.", correct:"bit", distractors:["bite","bitten","biting"], ex:"bite the bullet 表示「硬著頭皮去做困難的事」，過去式為 bit。"},
  {id:314, type:"phrase", cat:"travel", text:"This souvenir is going to ___ me an arm and a leg.", correct:"cost", distractors:["take","spend","charge"], ex:"cost someone an arm and a leg 表示「非常昂貴」。"},
  {id:315, type:"phrase", cat:"daily", text:"I'm starting to ___ cold feet about this whole plan.", correct:"get", distractors:["catch","feel","hold"], ex:"get cold feet 表示「（事到臨頭）開始緊張、退縮」。"},
  {id:316, type:"phrase", cat:"travel", text:"We hit the nail on the ___ when we guessed it would rain.", correct:"head", distractors:["spot","point","top"], ex:"hit the nail on the head 表示「一語中的、說中要點」。"},
  {id:317, type:"phrase", cat:"daily", text:"By combining the trip with a work conference, we're killing two birds with one ___.", correct:"stone", distractors:["shot","rock","arrow"], ex:"kill two birds with one stone 表示「一舉兩得」。"},
  {id:318, type:"phrase", cat:"travel", text:"She accidentally let the cat out of the ___ about the surprise trip.", correct:"bag", distractors:["box","house","hat"], ex:"let the cat out of the bag 表示「不小心洩漏秘密」。"},
  {id:319, type:"phrase", cat:"daily", text:"We only go to that restaurant once in a blue ___.", correct:"moon", distractors:["sky","night","star"], ex:"once in a blue moon 表示「很少發生、難得一次」。"},
  {id:320, type:"phrase", cat:"travel", text:"The ball is really in their ___ now — we've sent the complaint.", correct:"court", distractors:["hands","field","side"], ex:"the ball is in someone's court 表示「輪到某人做決定或行動了」。"},
  {id:321, type:"phrase", cat:"daily", text:"I think we're finally on the same ___ about the budget.", correct:"page", distractors:["track","line","level"], ex:"be on the same page 表示「想法一致」。"},
  {id:322, type:"phrase", cat:"travel", text:"In the ___ run, flying direct will save us both time and money.", correct:"long", distractors:["far","short","wide"], ex:"in the long run 表示「長遠來看」。"},
  {id:323, type:"phrase", cat:"daily", text:"With two jobs, it's hard to make ___ meet some months.", correct:"ends", distractors:["money","both","things"], ex:"make ends meet 表示「收支平衡、勉強維持生計」。"},
  {id:324, type:"phrase", cat:"travel", text:"A delayed flight is just ___ for the course when you travel a lot.", correct:"par", distractors:["part","fine","normal"], ex:"par for the course 表示「意料中的事、家常便飯」。"},
  {id:325, type:"phrase", cat:"daily", text:"Losing the flight booking was honestly the last ___.", correct:"straw", distractors:["thing","drop","step"], ex:"the last straw 表示「使人忍無可忍的最後一根稻草」。"},
  {id:326, type:"phrase", cat:"travel", text:"Time really does ___ when you're having fun on holiday.", correct:"fly", distractors:["run","go","jump"], ex:"time flies 表示「時間過得很快」。"},
  {id:327, type:"phrase", cat:"daily", text:"We're up ___ the air about whether to go this weekend.", correct:"in", distractors:["on","at","with"], ex:"be up in the air 表示「尚未決定、懸而未決」。"},
  {id:328, type:"phrase", cat:"travel", text:"After the cancellation, we were back to square ___.", correct:"one", distractors:["zero","two","start"], ex:"back to square one 表示「（計畫失敗）回到原點」。"},
  {id:329, type:"phrase", cat:"daily", text:"I know we're on a budget, but let's not ___ corners on safety.", correct:"cut", distractors:["turn","take","make"], ex:"cut corners 表示「為了省錢省事而降低品質」。"},
  {id:330, type:"phrase", cat:"travel", text:"Out of the ___, she suggested we extend the trip by a week.", correct:"blue", distractors:["sky","dark","clear"], ex:"out of the blue 表示「突然、毫無預警地」。"},
  {id:331, type:"phrase", cat:"daily", text:"That's certainly food for ___ — I hadn't considered it that way.", correct:"thought", distractors:["mind","brain","ideas"], ex:"food for thought 表示「值得深思的事」。"},
  {id:332, type:"phrase", cat:"travel", text:"I'll give you a call to ___ base once we land.", correct:"touch", distractors:["reach","hit","make"], ex:"touch base 表示「聯繫、互相更新近況」。"},
  {id:333, type:"phrase", cat:"daily", text:"Could you keep me ___ on how the renovation is going?", correct:"posted", distractors:["told","known","aware"], ex:"keep someone posted 表示「隨時讓某人知道最新狀況」。"},
  {id:334, type:"phrase", cat:"travel", text:"Let's ___ around a bit longer — there's still more to explore.", correct:"stick", distractors:["hold","wait","keep"], ex:"stick around 表示「多留一會兒、不要走」。"},
  {id:335, type:"phrase", cat:"daily", text:"That name doesn't ___ a bell — I don't think we've met.", correct:"ring", distractors:["sound","hit","strike"], ex:"ring a bell 表示「聽起來耳熟」。"},
  {id:336, type:"phrase", cat:"travel", text:"We're just scratching the ___ of what this country has to offer.", correct:"surface", distractors:["top","edge","start"], ex:"scratch the surface 表示「只觸及表面、了解得很有限」。"},
  {id:337, type:"phrase", cat:"daily", text:"I think we should ___ outside the box for this year's trip idea.", correct:"think", distractors:["go","step","look"], ex:"think outside the box 表示「跳脫框架思考」。"},
  {id:338, type:"phrase", cat:"travel", text:"Could I take a ___ on dinner tonight? Something came up.", correct:"rain check", distractors:["rain stop","weather check","sky check"], ex:"take a rain check 表示「婉拒邀約，改約下次」。"},
  {id:339, type:"phrase", cat:"daily", text:"I'd like to ___ face by fixing this myself before anyone notices.", correct:"save", distractors:["keep","make","hold"], ex:"save face 表示「保住面子」。"},
  {id:340, type:"phrase", cat:"travel", text:"We're really just ___ it by ear with this part of the trip — no fixed plan.", correct:"playing", distractors:["making","taking","going"], ex:"play it by ear 表示「臨機應變、走一步算一步」。"},
  {id:341, type:"phrase", cat:"daily", text:"Could you ___ the table for dinner tonight, around 7?", correct:"book", distractors:["take","hold","make"], ex:"book a table 表示「訂位」。"},
  {id:342, type:"phrase", cat:"travel", text:"Could we get separate ___, please? We're not splitting the bill.", correct:"checks", distractors:["bills","tickets","receipts"], ex:"separate checks 是「分開結帳」的常見說法。"},
  {id:343, type:"phrase", cat:"daily", text:"Is this dish included, or is it ___?", correct:"extra", distractors:["more","plus","added"], ex:"extra 表示「額外加收費用的」。"},
  {id:344, type:"phrase", cat:"travel", text:"We'd like our steaks cooked medium ___, not fully done.", correct:"rare", distractors:["raw","fresh","light"], ex:"medium rare 是牛排「五分熟」的固定說法。"},
  {id:345, type:"phrase", cat:"daily", text:"Could we get the leftovers in a ___ bag?", correct:"doggy", distractors:["puppy","carry","take"], ex:"doggy bag 表示打包剩菜用的「外帶袋」。"},
  {id:346, type:"phrase", cat:"travel", text:"Dinner's on the ___ tonight — happy anniversary!", correct:"house", distractors:["table","menu","bill"], ex:"on the house 表示「店家招待、免費」。"},
  {id:347, type:"phrase", cat:"daily", text:"We'll need a ___ for four at eight o'clock.", correct:"table", distractors:["seat","booking","spot"], ex:"a table for + 人數，是餐廳訂位常用句型。"},
  {id:348, type:"phrase", cat:"travel", text:"Could you let the kitchen know about any dietary ___ we have?", correct:"restrictions", distractors:["limits","rules","conditions"], ex:"dietary restrictions 表示「飲食限制（如過敏、素食等）」。"},
  {id:349, type:"phrase", cat:"daily", text:"Excuse me, could we get the ___ when you have a moment?", correct:"check", distractors:["receipt","ticket","total"], ex:"get the check 表示「請服務生拿帳單來」。"},
  {id:350, type:"phrase", cat:"travel", text:"Our flight has a two-hour ___ in Singapore.", correct:"layover", distractors:["delay","detour","transfer"], ex:"layover 表示轉機時的「短暫停留」。"},
  {id:351, type:"phrase", cat:"travel", text:"We're going to need to declare this at ___ when we arrive.", correct:"customs", distractors:["immigration","security","border"], ex:"declare something at customs，customs 專指「海關」，負責申報物品檢查。"},
  {id:352, type:"phrase", cat:"daily", text:"I'll need to see some ID before I can ___ you a refund.", correct:"issue", distractors:["pass","hand","make"], ex:"issue a refund 是較正式的說法，常用於商業情境。"},
  {id:353, type:"phrase", cat:"travel", text:"Could you show me where the ___ claim area is?", correct:"baggage", distractors:["suitcase","cargo","package"], ex:"baggage claim 是機場「行李提領處」的固定用語。"},
  {id:354, type:"phrase", cat:"daily", text:"This jacket is final sale — it's ___-refundable.", correct:"non", distractors:["un","de","dis"], ex:"non-refundable 表示「不可退費的」，non- 是常見否定字首。"},
  {id:355, type:"phrase", cat:"travel", text:"We managed to snag a ___-minute deal on flights.", correct:"last", distractors:["final","late","short"], ex:"last-minute deal 表示「最後一刻才出現的優惠」。"},
  {id:356, type:"phrase", cat:"daily", text:"It's best to book ___ during peak season — places fill up fast.", correct:"ahead", distractors:["forward","upfront","early on"], ex:"book ahead 表示「提前預訂」。"},
  {id:357, type:"phrase", cat:"travel", text:"This package deal is ___-inclusive — flights, hotel, and meals.", correct:"all", distractors:["full","total","whole"], ex:"all-inclusive 表示「包套全包式」。"},
  {id:358, type:"phrase", cat:"daily", text:"We're staying somewhere with self-___ facilities so we can cook.", correct:"catering", distractors:["service","care","sufficient"], ex:"self-catering 表示「（住宿）提供自炊設備」。"},
  {id:359, type:"phrase", cat:"travel", text:"The room comes with breakfast ___ — no extra charge.", correct:"complimentary", distractors:["complementary","compliant","competent"], ex:"complimentary 表示「免費贈送的」，常與形似字 complementary（互補的）混淆。"},
  {id:360, type:"phrase", cat:"daily", text:"We're fully ___ tonight — I'm afraid there's no availability.", correct:"booked", distractors:["filled","taken","reserved"], ex:"fully booked 表示「（旅館、餐廳）已被訂滿」。"},
  {id:361, type:"phrase", cat:"travel", text:"Tickets for the show are completely ___ — try again next week.", correct:"sold out", distractors:["sold off","all sold","out of sale"], ex:"sold out 表示「（票券、商品）售罄」。"},
  {id:362, type:"phrase", cat:"daily", text:"Please ___ your seatbelt before we begin our descent.", correct:"fasten", distractors:["tighten","tie","lock"], ex:"fasten one's seatbelt 是固定搭配，表示「繫上安全帶」。"},
  {id:363, type:"phrase", cat:"travel", text:"Please make sure your seat back is upright and your tray table is ___.", correct:"stowed", distractors:["stored","packed","closed"], ex:"stowed 是航空用語，表示「（小桌板）收起」。"},
  {id:364, type:"phrase", cat:"daily", text:"There's no more room in the overhead ___ for your bag.", correct:"compartment", distractors:["bin","cabinet","locker"], ex:"overhead compartment 是飛機上方的「行李櫃」。"},
  {id:365, type:"phrase", cat:"travel", text:"We checked the ___ and found section B for our items.", correct:"lost and found", distractors:["found and lost","lost office","claim desk"], ex:"lost and found 表示「失物招領處」。"},
  {id:366, type:"phrase", cat:"daily", text:"I think the printer is finally ___ to give up the ghost.", correct:"about", distractors:["going","set","due"], ex:"be about to V，表示「即將要…」；give up the ghost 是俏皮說法，表示機器「壽終正寢」。"},
  {id:367, type:"phrase", cat:"travel", text:"We're hoping to get a visa ___ when we land, to save time.", correct:"on arrival", distractors:["on landing","at entry","upon entry"], ex:"visa on arrival 是固定用語，指「落地簽證」。"},
  {id:368, type:"phrase", cat:"daily", text:"Could you keep this ___? I'd rather not make it public yet.", correct:"under wraps", distractors:["under cover","in secret","off record"], ex:"keep something under wraps 表示「保密、暫不公開」。"},
  {id:369, type:"phrase", cat:"travel", text:"We're trying to travel ___ a budget this year.", correct:"on", distractors:["with","in","by"], ex:"on a budget 表示「省著花、量入為出」。"},
  {id:370, type:"phrase", cat:"daily", text:"He tends to ___ his cards close to his chest in negotiations.", correct:"play", distractors:["keep","hold","hide"], ex:"play your cards close to your chest 表示「不輕易透露計畫或想法」。"},
  {id:371, type:"phrase", cat:"travel", text:"We're ___ for time, so let's skip the gift shop.", correct:"pressed", distractors:["pushed","short","late"], ex:"be pressed for time 表示「時間緊迫」。"},
  {id:372, type:"phrase", cat:"daily", text:"I'm running a bit behind ___, so I might be a few minutes late.", correct:"schedule", distractors:["time","clock","hour"], ex:"be running behind schedule 表示「進度落後、比預定時間晚」。"},
  {id:373, type:"phrase", cat:"travel", text:"We're trying to stay ___ schedule so we don't miss the train.", correct:"on", distractors:["in","by","at"], ex:"stay on schedule 表示「維持在預定的時間表上」。"},
  {id:374, type:"phrase", cat:"daily", text:"We need to ___ the bull by the horns and deal with this directly.", correct:"take", distractors:["grab","hold","catch"], ex:"take the bull by the horns 表示「果斷面對困難、正面處理」。"},
  {id:375, type:"phrase", cat:"travel", text:"We always try to ___ light when we travel — just one carry-on.", correct:"pack", distractors:["go","keep","travel"], ex:"pack light 表示「輕裝出行、少帶行李」。"},
  {id:376, type:"phrase", cat:"travel", text:"This part of the coast is still pretty ___ — not many tourists come here.", correct:"untouched", distractors:["unknown","unseen","untold"], ex:"untouched 表示「未受破壞、保持原始樣貌的」，常用於描述自然景觀。"},
  {id:377, type:"phrase", cat:"daily", text:"We should ___ tabs on the budget so we don't overspend.", correct:"keep", distractors:["hold","take","watch"], ex:"keep tabs on 表示「密切注意、追蹤」。"},
  {id:378, type:"phrase", cat:"travel", text:"Let's split up and ___ ground — we'll cover more of the city that way.", correct:"cover", distractors:["take","make","gain"], ex:"cover ground 表示「走過、涵蓋（一定範圍的距離或進度）」。"},
  {id:379, type:"phrase", cat:"daily", text:"Let's not ___ ahead of ourselves — we haven't even booked the flights yet.", correct:"get", distractors:["go","run","jump"], ex:"get ahead of oneself 表示「過早下定論、操之過急」。"},
  {id:380, type:"phrase", cat:"travel", text:"We're trying to ___ the most of our last day here.", correct:"make", distractors:["take","get","have"], ex:"make the most of 表示「充分利用」。"},
  {id:381, type:"phrase", cat:"daily", text:"It's a small office, so everyone has to ___ many hats.", correct:"wear", distractors:["hold","carry","take"], ex:"wear many hats 表示「身兼多職」。"},
  {id:382, type:"phrase", cat:"travel", text:"We're going to ___ it slow on the first day to deal with jet lag.", correct:"take", distractors:["go","make","keep"], ex:"take it slow 表示「放慢步調、不要太趕」。"},
  {id:383, type:"phrase", cat:"daily", text:"I really need to ___ the hang of this new software.", correct:"get", distractors:["catch","take","make"], ex:"get the hang of 表示「抓到訣竅、學會」。"},
  {id:384, type:"phrase", cat:"travel", text:"We're trying to ___ our bearings after such a long flight.", correct:"find", distractors:["get","take","make"], ex:"find one's bearings 表示「（搞清楚方向後）重新定位、適應環境」。"},
  {id:385, type:"phrase", cat:"daily", text:"He's still trying to ___ the ropes in his new role.", correct:"learn", distractors:["get","find","take"], ex:"learn the ropes 表示「學習訣竅、上手新工作」。"},
  {id:386, type:"phrase", cat:"travel", text:"We're hoping to ___ off the grid for a few days — no phones, no wifi.", correct:"go", distractors:["stay","get","fall"], ex:"go off the grid 表示「遠離通訊與現代生活的便利設施」。"},
  {id:387, type:"phrase", cat:"daily", text:"I think it's safe to ___ that the meeting went well.", correct:"say", distractors:["tell","speak","state"], ex:"it's safe to say that... 表示「可以這麼說、大致可以肯定」。"},
  {id:388, type:"phrase", cat:"travel", text:"We're going to ___ the day exploring the old town on foot.", correct:"spend", distractors:["pass","take","use"], ex:"spend the day + Ving，表示「花一整天做某事」。"},
  {id:389, type:"phrase", cat:"daily", text:"I'll ___ you know as soon as I hear back from them.", correct:"let", distractors:["make","keep","give"], ex:"let someone know 表示「讓某人知道」。"},
  {id:390, type:"phrase", cat:"travel", text:"We're going to ___ it a day and head back to the hotel.", correct:"call", distractors:["make","take","leave"], ex:"call it a day 表示「（活動）到此為止」，與 call it a night 意思相近但用於白天活動結束時。"},

  // ---------- Vocab batch (391-500) ----------
  {id:391, type:"vocab", cat:"daily", text:"The two cities have very different ___ systems.", correct:"economic", distractors:["economical","economy","economics"], ex:"economic 表示「經濟的（與經濟學相關）」，economical 表示「節省的、划算的」，兩字常混淆。"},
  {id:392, type:"vocab", cat:"travel", text:"This guesthouse is very ___ — great value for the price.", correct:"economical", distractors:["economic","economy","economics"], ex:"economical 表示「節省的、划算的」，與 economic（經濟的）不同。"},
  {id:393, type:"vocab", cat:"daily", text:"Please stand ___ the yellow line while waiting.", correct:"behind", distractors:["beside","between","among"], ex:"behind 表示「在…後方」。"},
  {id:394, type:"vocab", cat:"travel", text:"The hotel is conveniently located ___ the train station.", correct:"beside", distractors:["besides","between","among"], ex:"beside（在旁邊）與 besides（此外）拼字相近但詞性意義不同，besides 是「除了…之外」。"},
  {id:395, type:"vocab", cat:"daily", text:"I have no one to blame ___ myself for this mistake.", correct:"except", distractors:["accept","beside","besides"], ex:"except 表示「除了…之外（不包括）」，accept 是「接受」的動詞，拼字相近常混淆。"},
  {id:396, type:"vocab", cat:"travel", text:"We managed to find a ___ spot just off the main tourist trail.", correct:"picturesque", distractors:["picture","pictorial","pictured"], ex:"picturesque 表示「風景如畫的」。"},
  {id:397, type:"vocab", cat:"daily", text:"The committee will ___ the budget proposal next week.", correct:"review", distractors:["renew","renounce","renovate"], ex:"review 表示「審查、檢視」。"},
  {id:398, type:"vocab", cat:"travel", text:"This area is known for its ___ scenery and quiet beaches.", correct:"unspoiled", distractors:["unspoken","spoiled","spoilt"], ex:"unspoiled 表示「未受破壞、保持原始狀態的」。"},
  {id:399, type:"vocab", cat:"daily", text:"I really need to ___ my schedule this week — it's too packed.", correct:"streamline", distractors:["stream","straighten","streamlined"], ex:"streamline 表示「簡化、使更有效率」。"},
  {id:400, type:"vocab", cat:"travel", text:"The local market offers a great variety of ___ produce.", correct:"fresh", distractors:["freshly","freshness","freshen"], ex:"fresh 是形容詞，直接修飾名詞 produce。"},
  {id:401, type:"vocab", cat:"daily", text:"It's hard to ___ between the two candidates — they're both excellent.", correct:"choose", distractors:["chose","choosing","chosen"], ex:"句中需要原形動詞 choose，因為前面是 hard to V 的結構。"},
  {id:402, type:"vocab", cat:"travel", text:"The flight attendant gave us a quick ___ of the safety procedures.", correct:"overview", distractors:["oversee","overlook","overlap"], ex:"overview 表示「概述、簡介」。"},
  {id:403, type:"vocab", cat:"daily", text:"I'd like to ___ my subscription before it renews automatically.", correct:"cancel", distractors:["cancelled","cancelling","cancels"], ex:"句中需要原形動詞 cancel，因為前面是 would like to V 的結構。"},
  {id:404, type:"vocab", cat:"travel", text:"The tour was a bit ___ — we barely had time to see anything.", correct:"rushed", distractors:["rush","rushing","rushes"], ex:"rushed 是過去分詞作形容詞，表示「匆忙倉促的」。"},
  {id:405, type:"vocab", cat:"daily", text:"He's quite ___ about his achievements — never likes to brag.", correct:"modest", distractors:["modesty","modestly","model"], ex:"modest 是形容詞，表示「謙虛的」。"},
  {id:406, type:"vocab", cat:"travel", text:"We were warned to watch out for ___ in crowded tourist areas.", correct:"pickpockets", distractors:["picklocks","pickups","picketers"], ex:"pickpocket 表示「扒手」。"},
  {id:407, type:"vocab", cat:"daily", text:"The new manager has a very ___ approach to problem-solving.", correct:"practical", distractors:["practice","practically","practitioner"], ex:"practical 是形容詞，修飾名詞 approach。"},
  {id:408, type:"vocab", cat:"travel", text:"We booked a guided tour that includes ___ entry to the museum.", correct:"skip-the-line", distractors:["skip-line","skipping-line","line-skip"], ex:"skip-the-line 是固定複合形容詞，表示「免排隊」。"},
  {id:409, type:"vocab", cat:"daily", text:"I think there's been some ___ — I never agreed to that.", correct:"misunderstanding", distractors:["misunderstand","misunderstood","misunderstands"], ex:"此處需要名詞 misunderstanding（誤會）。"},
  {id:410, type:"vocab", cat:"travel", text:"The ferry schedule is ___ to change depending on the weather.", correct:"subject", distractors:["subjected","subjective","subjectively"], ex:"be subject to 表示「容易受…影響、視…而定」。"},
  {id:411, type:"vocab", cat:"daily", text:"She has a ___ for remembering people's names.", correct:"knack", distractors:["custom","manner","style"], ex:"have a knack for 表示「對…有訣竅、天分」。"},
  {id:412, type:"vocab", cat:"travel", text:"This neighborhood has a real ___ feel to it — very different from downtown.", correct:"local", distractors:["locally","locale","location"], ex:"local 是形容詞，修飾名詞 feel。"},
  {id:413, type:"vocab", cat:"daily", text:"I appreciate your ___, but I'd rather handle this myself.", correct:"concern", distractors:["concerned","concerning","concerns"], ex:"此處需要名詞 concern（關心、擔憂）。"},
  {id:414, type:"vocab", cat:"travel", text:"The view from our balcony was simply ___.", correct:"spectacular", distractors:["spectator","spectacle","spectacularly"], ex:"spectacular 是形容詞，表示「壯觀的」。"},
  {id:415, type:"vocab", cat:"daily", text:"He gave a rather ___ excuse for being late again.", correct:"flimsy", distractors:["flashy","fluffy","filthy"], ex:"flimsy 表示「站不住腳的、薄弱的（理由）」。"},
  {id:416, type:"vocab", cat:"travel", text:"We're looking for ___ accommodation, nothing too fancy.", correct:"budget", distractors:["budgeted","budgeting","budgetary"], ex:"budget 在此作形容詞用，修飾名詞 accommodation，表示「經濟實惠的」。"},
  {id:417, type:"vocab", cat:"daily", text:"It's important to stay ___ when discussing sensitive topics at work.", correct:"diplomatic", distractors:["diplomat","diplomacy","diplomatically"], ex:"diplomatic 是形容詞，表示「圓融的、有外交手腕的」。"},
  {id:418, type:"vocab", cat:"travel", text:"The area is popular with hikers because of its ___ trails.", correct:"scenic", distractors:["scenery","scene","scenically"], ex:"scenic 是形容詞，修飾名詞 trails，表示「風景優美的」。"},
  {id:419, type:"vocab", cat:"daily", text:"I think we should ___ this decision until we have more information.", correct:"postpone", distractors:["postponed","postponing","postpones"], ex:"句中需要原形動詞 postpone，前面是 should + 原形動詞。"},
  {id:420, type:"vocab", cat:"travel", text:"We're trying to find a more ___ way to get around the city.", correct:"convenient", distractors:["convenience","conveniently","convene"], ex:"convenient 是形容詞，修飾名詞 way。"},
  {id:421, type:"vocab", cat:"daily", text:"Her presentation was clear, concise, and very ___.", correct:"persuasive", distractors:["persuade","persuasion","persuasively"], ex:"persuasive 是形容詞，表示「有說服力的」。"},
  {id:422, type:"vocab", cat:"travel", text:"We were lucky to get a room with such a ___ view.", correct:"stunning", distractors:["stun","stunned","stuns"], ex:"stunning 是現在分詞作形容詞，表示「令人驚艷的」。"},
  {id:423, type:"vocab", cat:"daily", text:"I think his comment was a bit ___, given the situation.", correct:"insensitive", distractors:["insensible","unsensitive","sensitive"], ex:"insensitive 表示「不顧及他人感受的」，insensible 則表示「失去知覺的」，兩字常混淆。"},
  {id:424, type:"vocab", cat:"travel", text:"The locals were incredibly ___ when we got lost.", correct:"helpful", distractors:["helpless","helping","helpfully"], ex:"helpful（樂於助人的）與 helpless（無助的）意思相反，拼字相近易混淆。"},
  {id:425, type:"vocab", cat:"daily", text:"I was completely ___ by how well the presentation went.", correct:"astonished", distractors:["astonishing","astonish","astonishment"], ex:"astonished 描述「（人）感到驚訝的」，astonishing 則描述「令人驚訝的（事物）」。"},
  {id:426, type:"vocab", cat:"travel", text:"The scenery along this route is absolutely ___.", correct:"magnificent", distractors:["magnify","magnitude","magnificently"], ex:"magnificent 是形容詞，表示「壯麗的、宏偉的」。"},
  {id:427, type:"vocab", cat:"daily", text:"He's quite ___ when it comes to handling criticism.", correct:"resilient", distractors:["resistant","resident","residential"], ex:"resilient 表示「有韌性的、能很快恢復的」。"},
  {id:428, type:"vocab", cat:"travel", text:"This trail is fairly ___, so wear good shoes.", correct:"rugged", distractors:["ragged","rugby","rigid"], ex:"rugged 表示「崎嶇不平的（地形）」，與 ragged（破爛的）拼字相近易混淆。"},
  {id:429, type:"vocab", cat:"daily", text:"I think we need a more ___ approach to solving this.", correct:"systematic", distractors:["systemic","systematically","system"], ex:"systematic 表示「有條理的、按部就班的」，systemic 則多用於「（疾病等）全身性的」。"},
  {id:430, type:"vocab", cat:"travel", text:"We need to ___ our route before setting off.", correct:"plan", distractors:["planned","planning","plans"], ex:"句中需要原形動詞 plan，前面是 need to V 的結構。"},
  {id:431, type:"vocab", cat:"daily", text:"She remained perfectly ___ throughout the whole crisis.", correct:"composed", distractors:["composing","compose","composition"], ex:"composed 是過去分詞作形容詞，表示「鎮定的」。"},
  {id:432, type:"vocab", cat:"travel", text:"The currency here is quite ___, so check the rate daily.", correct:"volatile", distractors:["violate","volume","voluntary"], ex:"volatile 表示「（匯率、市場）不穩定、易波動的」。"},
  {id:433, type:"vocab", cat:"daily", text:"I really admire how ___ she stays under pressure.", correct:"calm", distractors:["calmly","calmness","calming"], ex:"此處需要形容詞 calm 作主詞補語。"},
  {id:434, type:"vocab", cat:"travel", text:"The local cuisine here is incredibly ___ — lots of bold spices.", correct:"flavorful", distractors:["flavored","flavoring","flavor"], ex:"flavorful 是形容詞，表示「風味十足的」。"},
  {id:435, type:"vocab", cat:"daily", text:"He's notorious for being ___ with his money.", correct:"stingy", distractors:["sting","stinging","stingily"], ex:"stingy 是形容詞，表示「小氣的」。"},
  {id:436, type:"vocab", cat:"travel", text:"We found a hidden ___ just a short walk from the main square.", correct:"gem", distractors:["jewel","diamond","stone"], ex:"a hidden gem 是固定用語，表示「鮮為人知卻很棒的地方」。"},
  {id:437, type:"vocab", cat:"daily", text:"I think the report could be more ___ — it's quite repetitive.", correct:"concise", distractors:["precise","conceited","accurate"], ex:"concise 表示「簡潔的」，precise 表示「精確的」，意思不同。"},
  {id:438, type:"vocab", cat:"travel", text:"Don't forget to bring ___ shoes for all the walking we'll be doing.", correct:"comfortable", distractors:["comfort","comforting","comfortably"], ex:"comfortable 是形容詞，修飾名詞 shoes。"},
  {id:439, type:"vocab", cat:"daily", text:"It was a ___ decision, but I think it was the right one.", correct:"tough", distractors:["toughen","toughness","toughly"], ex:"tough 是形容詞，表示「困難的、艱難的」。"},
  {id:440, type:"vocab", cat:"travel", text:"The trail offers ___ views of the entire valley.", correct:"panoramic", distractors:["panorama","panoramically","panoramas"], ex:"panoramic 是形容詞，修飾名詞 views，表示「全景的」。"},
  {id:441, type:"vocab", cat:"daily", text:"I'd like to ___ my appreciation for everything you've done.", correct:"express", distractors:["expressed","expressing","expresses"], ex:"句中需要原形動詞 express，前面是 would like to V。"},
  {id:442, type:"vocab", cat:"travel", text:"This region is ___ for its handmade pottery.", correct:"renowned", distractors:["renown","renews","renewed"], ex:"be renowned for 表示「以…聞名」，renowned 是形容詞。"},
  {id:443, type:"vocab", cat:"daily", text:"He has a tendency to ___ everything, even small decisions.", correct:"overthink", distractors:["overtake","overlook","overdo"], ex:"overthink 表示「過度思考」。"},
  {id:444, type:"vocab", cat:"travel", text:"We're trying to travel more ___ this year — fewer flights, more trains.", correct:"sustainably", distractors:["sustainable","sustain","sustainability"], ex:"此處需要副詞 sustainably 修飾動詞 travel。"},
  {id:445, type:"vocab", cat:"daily", text:"The instructions were ___, so we had no trouble assembling it.", correct:"straightforward", distractors:["straightaway","forward","straight"], ex:"straightforward 表示「簡單明瞭的」。"},
  {id:446, type:"vocab", cat:"travel", text:"We're hoping for ___ weather for the boat trip tomorrow.", correct:"favorable", distractors:["favorite","favored","favorably"], ex:"favorable 是形容詞，表示「有利的、適宜的」。"},
  {id:447, type:"vocab", cat:"daily", text:"It's ___ that he hasn't called back yet — that's not like him.", correct:"odd", distractors:["odds","oddly","oddity"], ex:"odd 是形容詞，表示「奇怪的」。"},
  {id:448, type:"vocab", cat:"travel", text:"The city's old quarter is full of ___ architecture.", correct:"charming", distractors:["charm","charmed","charmingly"], ex:"charming 是現在分詞作形容詞，表示「迷人的」。"},
  {id:449, type:"vocab", cat:"daily", text:"I think we should take a more ___ approach to this project.", correct:"cautious", distractors:["caution","cautiously","cautioned"], ex:"cautious 是形容詞，修飾名詞 approach。"},
  {id:450, type:"vocab", cat:"travel", text:"The boat ride was a bit ___ — the water was choppy.", correct:"bumpy", distractors:["bumped","bumping","bumps"], ex:"bumpy 是形容詞，表示「顛簸的」。"},
  {id:451, type:"vocab", cat:"daily", text:"He's known for being quite ___ in meetings — always straight to the point.", correct:"blunt", distractors:["bluntly","blunted","bluntness"], ex:"blunt 是形容詞，表示「直率的、不拐彎抹角的」。"},
  {id:452, type:"vocab", cat:"travel", text:"This dish is a local ___ — you won't find it anywhere else.", correct:"specialty", distractors:["special","specially","specialize"], ex:"specialty 是名詞，表示「特色菜、招牌菜」。"},
  {id:453, type:"vocab", cat:"daily", text:"I think the new policy is ___ — it solves several problems at once.", correct:"effective", distractors:["affective","effect","effectively"], ex:"effective 表示「有效的」，affective 則是心理學用語「情感的」，兩字常混淆。"},
  {id:454, type:"vocab", cat:"travel", text:"We need to be ___ of the time difference when calling home.", correct:"mindful", distractors:["minded","mindless","minding"], ex:"be mindful of 表示「留意、注意」。"},
  {id:455, type:"vocab", cat:"daily", text:"The new intern is incredibly ___ — always asking great questions.", correct:"inquisitive", distractors:["inquiry","inquire","inquired"], ex:"inquisitive 是形容詞，表示「好奇求知的」。"},
  {id:456, type:"vocab", cat:"travel", text:"It's worth taking a guided tour to get some ___ into the local history.", correct:"insight", distractors:["sight","insightful","incite"], ex:"insight 是名詞，表示「深入的了解、洞察」。"},
  {id:457, type:"vocab", cat:"daily", text:"I think he was being ___ when he said the project was nearly done.", correct:"optimistic", distractors:["optimal","optimum","optimize"], ex:"optimistic 表示「樂觀的」。"},
  {id:458, type:"vocab", cat:"travel", text:"The trail can get quite ___, so bring plenty of water.", correct:"strenuous", distractors:["strength","strengthen","strenuously"], ex:"strenuous 是形容詞，表示「費力的、艱辛的」。"},
  {id:459, type:"vocab", cat:"daily", text:"She handled the complaint with great ___.", correct:"tact", distractors:["tactic","tactics","tactical"], ex:"tact 是名詞，表示「圓融、得體的處事方式」，與 tactic（戰術）拼字相近但意思不同。"},
  {id:460, type:"vocab", cat:"travel", text:"We're trying to keep our itinerary fairly ___ in case plans change.", correct:"flexible", distractors:["flexibility","flexibly","flex"], ex:"flexible 是形容詞，修飾名詞 itinerary，表示「有彈性的」。"},
  {id:461, type:"vocab", cat:"daily", text:"His argument was logical, but I found it ___ unconvincing.", correct:"ultimately", distractors:["ultimate","ultimatum","ultimating"], ex:"ultimately 是副詞，表示「最終、歸根究底」。"},
  {id:462, type:"vocab", cat:"travel", text:"The tour operator was very ___ when we had to cancel last minute.", correct:"accommodating", distractors:["accommodation","accommodate","accommodated"], ex:"accommodating 是形容詞，表示「樂於配合、體諒的」。"},
  {id:463, type:"vocab", cat:"daily", text:"I think the meeting could have been ___ into a quick email.", correct:"condensed", distractors:["condense","condensing","condensation"], ex:"condensed 是過去分詞作形容詞，表示「濃縮、簡化的」。"},
  {id:464, type:"vocab", cat:"travel", text:"We had a slight ___ over which restaurant to choose.", correct:"disagreement", distractors:["disagree","disagreeable","disagreed"], ex:"此處需要名詞 disagreement。"},
  {id:465, type:"vocab", cat:"daily", text:"The contract includes a ___ clause in case either party wants out.", correct:"termination", distractors:["terminate","terminal","terminally"], ex:"此處需要名詞 termination 修飾 clause。"},
  {id:466, type:"vocab", cat:"travel", text:"This part of the trip is entirely ___ — no fixed schedule at all.", correct:"unplanned", distractors:["planless","unplan","planned"], ex:"unplanned 表示「沒有計畫的、即興的」。"},
  {id:467, type:"vocab", cat:"daily", text:"I think we should ___ the meeting to next Tuesday.", correct:"reschedule", distractors:["rescheduled","rescheduling","reschedules"], ex:"句中需要原形動詞 reschedule，前面是 should + 原形動詞。"},
  {id:468, type:"vocab", cat:"travel", text:"The ferry ride offers ___ views of the coastline.", correct:"sweeping", distractors:["sweep","swept","sweeps"], ex:"sweeping 是現在分詞作形容詞，表示「遼闊壯觀的（視野）」。"},
  {id:469, type:"vocab", cat:"daily", text:"He's always been quite ___ about his personal life.", correct:"private", distractors:["privacy","privately","privatize"], ex:"private 是形容詞，表示「低調、不愛公開的」。"},
  {id:470, type:"vocab", cat:"travel", text:"We're trying to avoid the more ___ tourist spots this time.", correct:"crowded", distractors:["crowd","crowding","crowds"], ex:"crowded 是形容詞，表示「擁擠的」。"},
  {id:471, type:"vocab", cat:"daily", text:"I think his feedback was a bit ___ — hard to know what he actually meant.", correct:"vague", distractors:["vaguely","vagueness","vaguer"], ex:"vague 是形容詞，表示「模糊不清的」。"},
  {id:472, type:"vocab", cat:"travel", text:"We managed to find a ___ little café tucked away in a side street.", correct:"quaint", distractors:["quiet","quick","quite"], ex:"quaint 表示「古色古香、別有風味的」。"},
  {id:473, type:"vocab", cat:"daily", text:"I think we need a ___ solution, not just a quick fix.", correct:"long-term", distractors:["long-time","longtime","long term's"], ex:"long-term 是複合形容詞，表示「長期的」。"},
  {id:474, type:"vocab", cat:"travel", text:"The hike was more ___ than we expected — we were exhausted by the end.", correct:"demanding", distractors:["demand","demanded","demands"], ex:"demanding 是現在分詞作形容詞，表示「費力的、要求高的」。"},
  {id:475, type:"vocab", cat:"daily", text:"She gave a very ___ account of what happened.", correct:"detailed", distractors:["detail","detailing","details"], ex:"detailed 是過去分詞作形容詞，表示「詳細的」。"},
  {id:476, type:"vocab", cat:"travel", text:"The local guide was extremely ___ about the area's history.", correct:"knowledgeable", distractors:["knowledge","knowing","known"], ex:"knowledgeable 是形容詞，表示「博學的、知識豐富的」。"},
  {id:477, type:"vocab", cat:"daily", text:"I think it's worth being a bit more ___ before signing anything.", correct:"careful", distractors:["care","carefully","caring"], ex:"此處需要形容詞 careful 作主詞補語。"},
  {id:478, type:"vocab", cat:"travel", text:"The hotel's location is ___ — right next to the main attractions.", correct:"ideal", distractors:["idea","ideally","idealize"], ex:"ideal 是形容詞，表示「理想的」。"},
  {id:479, type:"vocab", cat:"daily", text:"I think he was just being ___ — he didn't really mean it.", correct:"sarcastic", distractors:["sarcasm","sarcastically","sardonic"], ex:"sarcastic 是形容詞，表示「諷刺挖苦的」。"},
  {id:480, type:"vocab", cat:"travel", text:"We're trying to find more ___ options for getting around, like biking.", correct:"eco-friendly", distractors:["eco-friend","environmentally","ecologic"], ex:"eco-friendly 是複合形容詞，表示「環保的」。"},
  {id:481, type:"vocab", cat:"daily", text:"He seemed quite ___ when I brought up the topic.", correct:"defensive", distractors:["defended","defending","defends"], ex:"defensive 是形容詞，表示「有防衛心的」。"},
  {id:482, type:"vocab", cat:"travel", text:"The street food here is surprisingly ___ — full of flavor.", correct:"delicious", distractors:["delicacy","delight","delightful"], ex:"delicious 是形容詞，專門用於形容「美味的」食物。"},
  {id:483, type:"vocab", cat:"daily", text:"I think we should be more ___ in our approach to saving money.", correct:"disciplined", distractors:["discipline","disciplinary","disciplining"], ex:"disciplined 是過去分詞作形容詞，表示「自律的」。"},
  {id:484, type:"vocab", cat:"travel", text:"The mountain pass is only ___ during the summer months.", correct:"accessible", distractors:["accessibility","access","accessibly"], ex:"accessible 是形容詞，表示「可到達、可進入的」。"},
  {id:485, type:"vocab", cat:"daily", text:"I think the proposal needs a bit more ___ before we present it.", correct:"polish", distractors:["polished","polishes","polite"], ex:"polish 在此作名詞，表示「潤飾、修整」。"},
  {id:486, type:"vocab", cat:"travel", text:"We're trying to plan a trip that's both fun and ___.", correct:"affordable", distractors:["afford","affording","affords"], ex:"affordable 是形容詞，表示「負擔得起的」。"},
  {id:487, type:"vocab", cat:"daily", text:"I think the design could be a little more ___.", correct:"refined", distractors:["refine","refining","refines"], ex:"refined 是過去分詞作形容詞，表示「精緻、講究的」。"},
  {id:488, type:"vocab", cat:"travel", text:"This part of town has a very ___ atmosphere — lots of street art and music.", correct:"vibrant", distractors:["vibrate","vibration","vibrantly"], ex:"vibrant 是形容詞，表示「生氣蓬勃的」。"},
  {id:489, type:"vocab", cat:"daily", text:"He's always been quite ___ when it comes to trying new things.", correct:"adventurous", distractors:["adventure","adventurer","adventurously"], ex:"adventurous 是形容詞，表示「有冒險精神的」。"},
  {id:490, type:"vocab", cat:"travel", text:"The old town's narrow streets are full of ___ charm.", correct:"rustic", distractors:["rusty","rustle","rust"], ex:"rustic 表示「鄉村風味的、質樸的」，與 rusty（生鏽的）拼字相近易混淆。"},
  {id:491, type:"vocab", cat:"daily", text:"I think we should take a more ___ stance on this issue.", correct:"firm", distractors:["firmly","firmness","confirm"], ex:"此處需要形容詞 firm 修飾名詞 stance。"},
  {id:492, type:"vocab", cat:"travel", text:"The coastal road offers some truly ___ views.", correct:"dramatic", distractors:["drama","dramatically","dramatize"], ex:"dramatic 是形容詞，表示「壯觀、戲劇性的」。"},
  {id:493, type:"vocab", cat:"daily", text:"She's quite ___ about her morning routine — never skips a step.", correct:"meticulous", distractors:["meticulously","meticulousness","mechanical"], ex:"meticulous 是形容詞，表示「一絲不苟的」。"},
  {id:494, type:"vocab", cat:"travel", text:"We're hoping for a more ___ pace on this leg of the trip.", correct:"relaxed", distractors:["relax","relaxation","relaxing"], ex:"relaxed 是形容詞，表示「悠閒、不趕的」。"},
  {id:495, type:"vocab", cat:"daily", text:"I think the report is ___ enough to send as is.", correct:"polished", distractors:["polish","polishing","polishes"], ex:"polished 是過去分詞作形容詞，表示「完善、精緻的」。"},
  {id:496, type:"vocab", cat:"travel", text:"This dish is a bit too ___ for my taste — too much chili.", correct:"spicy", distractors:["spice","spiced","spices"], ex:"spicy 是形容詞，表示「辛辣的」。"},
  {id:497, type:"vocab", cat:"daily", text:"He's known for being quite ___ — always sees the bright side.", correct:"upbeat", distractors:["uptight","upright","upset"], ex:"upbeat 表示「樂觀開朗的」。"},
  {id:498, type:"vocab", cat:"travel", text:"The trail can be quite ___ after heavy rain, so be careful.", correct:"slippery", distractors:["slip","slipping","slips"], ex:"slippery 是形容詞，表示「濕滑的」。"},
  {id:499, type:"vocab", cat:"daily", text:"I think we should be more ___ about how we spend our free time.", correct:"intentional", distractors:["intention","intentionally","intend"], ex:"intentional 是形容詞，表示「有意識、刻意的」。"},
  {id:500, type:"vocab", cat:"travel", text:"After a long trip, it always feels good to ___ back into routine.", correct:"settle", distractors:["set","sit","settled"], ex:"settle back into 表示「重新適應、回到（日常生活）」。"}
];
